  str_guide_pop_title = "Chain Combo",
  str_guide_pop_desc = [[
Ketika Chain mencapai <color=#ff8f3d>panjang tertentu</color>, kamu akan <color=#ff8f3d>memulai Chain Combo secara otomatis</color>.
