  str_guide_warn_509005 = "Kau bisa menemukan banyak hal di sini, termasuk bibit pohoh. Chubb!",
  str_guide_warn_509006 = "Sekarang, mari kita cari tahu cara memakainya dengan bijak! Ketuk di sini untuk kembali.",
  str_guide_warn_510002 = "Ada tiga cara untuk membiakkan Chubb. Pembiakan Mutasi, Pembiakan Bertarget, dan Pembiakan Transformasi. Ayo kita coba Pembiakan Mutasi lebih dulu!",
  str_guide_warn_510003 = "Letakkan benih Unique Tree di sini sebagai Benih Subjek, Chubb.",
  str_guide_warn_510004 = "Tambahkan benih lain dengan kualitas yang sama di sini sebagai Mutation Factor, Chubb.",
  str_guide_warn_510005 = "Ketuk di sini untuk memulai pembiakan. Unique Tree akan tumbuh beberapa saat kemudian, Chubb!",
  str_guide_warn_510006 = "Kalau kamu tak ingin menunggu lama, gunakan Diluent untuk mempercepat prosesnya, Chubb.",
  str_guide_warn_510007 = "Kalau ada hal yang ingin ditanyakan, ketuk di sini untuk meminta bantuan, Chubb!",
  str_guide_warn_511001 = "Land of Fertility dapat ditemukan di tab Special Furnishing. Ketuk di sini, Chubb!",
  str_guide_warn_511002 = "Lalu, ketuk tab Land of Fertility, Chubb!",
  str_guide_warn_511003 = "Ini adalah Land of Fertility, Chubb! Dengan bidang tanah ini, kau bisa membiakkan Unique Tree, Chubb!",
  str_guide_warn_512001 = "Ketuk di sini untuk mendekorasi.",
  str_guide_warn_512002 = "Land of Fertility dapat ditemukan di tab Special Furnishing. Ketuk di sini!",
  str_guide_warn_512003 = "Lalu, ketuk tab Land of Fertility!",
  str_guide_warn_512004 = "Ini adalah Land of Fertility. Ketuk di sini untuk meletakkan!",
  str_guide_warn_5110001 = "Navigator, Aurorian telah mencapai level maksimum. Untuk meningkatkan level lebih lanjut, Anda harus menjalani Ascension untuk menembus batas saat ini.",
  str_guide_warn_5110004 = "Ketuk untuk melihat material yang dibutuhkan untuk Ascension!",
  str_guide_warn_5110005 = "Dalam kasus material tidak cukup, ada beberapa cara untuk mendapatkannya, termasuk mengumpulkannya dari tahapan yang sesuai atau meningkatkan level Workshop untuk membuatnya.",
  str_guide_warn_19050101 = "\"Trees, Fish and A Slow Life\" telah dimulai! Siap mengarungi petualangan baru?",
