  str_guide_warn_11000202 = "Gunakan Prism di tahap Main Story dan Resource Raid untuk mendapatkan Infiltrasi Point.",
  str_guide_warn_11000203 = "Menyusup ke Dungeon dari sini, konsumsi Poin Infiltrasi untuk mengalahkan musuh dan menerima berbagai hadiah!",
  str_guide_warn_11000204 = "Ini adalah tahap percobaan untuk Pencuri Phantom. Lengkapi untuk hadiah.",
  str_guide_warn_11000205 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
