  str_guide_warn_11000207 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11050101 = "Acara Summer's Breeze & The Port of Hope telah dimulai! Apakah Anda siap untuk petualangan baru?",
  str_guide_warn_11050102 = "Di Strange Alleyway Shadows, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11050103 = "Dalam Ramalan Hati, jadilah detektif dan selidiki kasus barang hilang dengan tiga wanita cantik!",
  str_guide_warn_11050104 = "Harbour Fair Coins yang diperoleh dengan menyelesaikan tahapan acara dan menghabiskan Prism dapat digunakan untuk menebus berbagai hadiah dari Street Fair.",
  str_guide_warn_11050105 = "Saat Anda bertualang, uji keterampilan memasak Anda di Food Cart King untuk memenangkan berbagai hadiah!",
  str_guide_warn_11050106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11050107 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11050108 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11050201 = "Pelanggan mulai mengantre... Kita harus mulai membuat lebih banyak udon secepat mungkin!",
  str_guide_warn_11050202 = "Setiap pelanggan akan meminta jenis udon yang berbeda. Pilih bahan yang tepat untuk membuatnya untuk mereka!",
  str_guide_warn_11050203 = "Semakin lama pelanggan menunggu, suasana hati mereka pun akan semakin memburuk. Semakin baik suasana hati mereka, semakin tinggi pula rating-mu!",
  str_guide_warn_11050204 = "Saat membuat udon, pertama-tama Anda harus memilih ukuran porsi yang benar.",
  str_guide_warn_11050205 = "Kemudian Anda dapat memilih sup.",
  str_guide_warn_11050206 = "Pilih bahan yang tepat! Urutan di mana Anda memilih bahan dan sup tidak masalah di sini!",
  str_guide_warn_11050207 = "Ketuk pelanggan untuk mengirimkan udon mereka, dan pesanan selesai!",
  str_guide_warn_11050208 = "Menyelesaikan sejumlah pesanan berturut-turut akan mengaktifkan Topping Frenzy, membantu Anda menyelesaikan pesanan berikut dalam hitungan detik!",
  str_guide_warn_11050209 = "Kamu juga akan mendapatkan bonus reward setelah menyelesaikan pesanan berurutan!",
  str_guide_warn_11050210 = "Jangan khawatir jika Anda membuat kesalahan saat menyiapkan udon—cukup ketuk di sini untuk membuangnya!",
  str_guide_warn_11050211 = "Ketuk di sini untuk berhenti memasak mie dan istirahat.",
  str_guide_warn_11050212 = "Dan hanya itu yang perlu Anda ketahui tentang membuat udon! Sekarang, mari kembali bekerja!",
  str_guide_warn_11100101 = "Acara Summer's Breeze & The Port of Hope telah dimulai! Apakah Anda siap untuk petualangan baru?",
  str_guide_warn_11100102 = "Morphing Card yang diperoleh dengan menyelesaikan tahapan Main Story atau Resource Raid yang membutuhkan Prism dapat digunakan untuk menebus berbagai hadiah dari Enchanted Valet Stand.",
  str_guide_warn_11100103 = "Semua orang di Cloud Gardens tampaknya sangat tertarik untuk membangun kolam renang. Kamu bisa memeriksa Cloud Gardens Feats yang baru di Let's Go Swimming!",
  str_guide_warn_11100104 = "Terus lacak sinyal dan temukan harta karun bersama Chubb di Detailed Investigation III!",
  str_guide_warn_11100105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11100106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11100107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11200101 = "Acara Perpisahan, \"Wonderland\" saya telah dimulai! Petualangan baru dimulai di sini dan sekarang.",
  str_guide_warn_11200102 = "Di No Man's Land, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11200103 = "Casing Cangkang Kosong yang diperoleh dengan menyelesaikan tahapan acara dan pengeluaran Prism dapat digunakan untuk menebus berbagai hadiah dari Depot Pasokan.",
  str_guide_warn_11200104 = "Di Street Errands, kami akan menjelajahi kota lebih jauh dan mengumpulkan informasi dan berita di jalanan.",
  str_guide_warn_11200105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11200106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11200107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11200203 = "Ini adalah pencarian yang berbahaya dan bermanfaat. Ayo pergi sekarang!",
  str_guide_warn_11200204 = "Lift pusat bisa membawa kita langsung ke kedalaman, tapi itu diisi dengan gas berbahaya di bawah, jadi tidak bisa dieksplorasi untuk saat ini.",
  str_guide_warn_11200205 = "Berikut daftar hadiah dari Illumina. Semakin dalam kita menjelajah, semakin banyak imbalan yang akan kita dapatkan.",
  str_guide_warn_11200206 = "Bagaimanapun, mari kita lihat apakah kita dapat menemukan cara untuk menghilangkan gas berbahaya!",
  str_guide_warn_11200207 = "Eclipsites telah menyita semua Ventilator di sini. Aktifkan semua Ventilator untuk menghilangkan gas berbahaya dan lanjutkan menjelajahi lantai berikutnya.",
  str_guide_warn_11200208 = "Anda perlu menempatkan 5 Aurorian di setiap Ventilator untuk mengaktifkannya. Ventilator tidak akan aktif jika Anda menarik Aurorian sebelum pemurnian selesai di lantai.",
  str_guide_warn_11200209 = "Aktifkan semua Ventilator dengan menempatkan beberapa tim dari Aurorian yang berbeda untuk melanjutkan penjelajahan.",
  str_guide_warn_11200210 = "Illumina telah memberikan informasi eksplorasi yang lebih detail. Ketuk di sini untuk melihatnya.",
  str_guide_warn_11300101 = "Satu Potong Jeritan! acara telah dimulai! Petualangan baru dimulai di sini dan sekarang.",
  str_guide_warn_11300102 = "Koin Antik yang diperoleh dengan menyelesaikan tahapan acara dan menghabiskan Prism dapat digunakan untuk menebus berbagai hadiah dari The Secret Room.",
  str_guide_warn_11300103 = "Semua orang di Cloud Gardens bersemangat membuat set film di Cloud Gardens! Anda dapat melihat Feat Cloud Gardens yang baru: Tetapkan Waktu Konstruksi!",
  str_guide_warn_11300104 = "Kita bisa mulai syuting setelah set selesai! Anda juga akan mendapatkan hadiah luar biasa dari Chubbs setelah syuting film!",
  str_guide_warn_11300105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11300106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11300107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11400102 = "Gunakan Prism untuk menyelesaikan stage Main Story dan Resource Raid untuk mendapatkan Scrap Parts dan memberikannya kepada Axelia untuk menggabungkannya! Anda akan dihargai dengan murah hati!",
  str_guide_warn_11400103 = "Semua orang di Cloud Gardens tampaknya bersemangat mengadakan kompetisi memancing. Lihat acara Cloud Gardens Feats baru: Tangkapan Luar Biasa!",
  str_guide_warn_11400104 = "Selesaikan tantangan dengan teman baru Anda untuk mendapatkan hadiah Lumamber!",
  str_guide_warn_11400105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11400106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11400107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11500101 = "Acara Starry Adventure: Heaven-Shaking Melody telah dimulai! Kami akan mengadakan konser unik bersama Goldie!",
  str_guide_warn_11500102 = "Dalam Dreamy Nostalgia, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11500103 = "Goldie Merch yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menebus berbagai hadiah dari Tabloid Brandy.",
  str_guide_warn_11500104 = "Sarang Eclipsite yang misterius telah muncul di dekat Wilayah Rahasia. Navigator dapat mengatasi rintangan dengan mempelajari Keterampilan Penguasaan Bakat dan menggunakan relik untuk mendapatkan Lumamber!",
  str_guide_warn_11500105 = "Di Starlit Agency, Navigator akan menjadi agen Goldie. Beri dia pelatihan dan atur kegiatan untuk akhirnya mengirimnya ke panggung konser!",
  str_guide_warn_11500106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11500107 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11500108 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11500201 = "Mari kita mulai, Navigator. Ini adalah Starlit Agency, tempat kami akan melatih para idola dan mengadakan acara untuk akhirnya mengangkat mereka ke atas panggung.",
  str_guide_warn_11500202 = "Agensi telah menetapkan beberapa tujuan untuk kami. Hadiah tersedia setelah selesai. Kenangan dari pelatihan juga akan dicatat di sini.",
  str_guide_warn_11500203 = "Jika Anda tidak puas dengan pelatihan, Anda dapat kembali memilih momen penting untuk membuat keputusan yang berbeda.",
  str_guide_warn_11500204 = "Saatnya memulai pelatihan, Navigator!",
  str_guide_warn_11500301 = "Ini adalah hitungan mundur sampai konser. 13 hari tersisa! Pekerjaan Anda cocok untuk Anda.",
  str_guide_warn_11500302 = "Tapi kita harus mendapatkan 150.000 fans sebelum kita bisa mengadakan konser.",
  str_guide_warn_11500303 = "Menjadi idola berarti banyak pelatihan. Ada tiga mode pelatihan yang tersedia. Pastikan Anda tetap tenang saat paparazzi muncul!",
  str_guide_warn_11500304 = "Inilah keterampilan idola saya. Mode pelatihan akan meningkatkannya.",
  str_guide_warn_11500305 = "Mengadakan acara dapat membantu kami mendapatkan lebih banyak penggemar sehingga kami dapat mencapai persyaratan untuk konser!",
  str_guide_warn_11500306 = "Berikut to-do list minggu ini, Anda bisa menggunakannya sebagai referensi untuk penjadwalan. Bicaralah dengan orang-orang selama pelatihan, dan Anda mungkin akan mendapatkan sesuatu darinya.",
  str_guide_warn_11500307 = "Informasi lainnya ada di Buku Pegangan Produsen. Konsultasikan kapan pun Anda membutuhkan sesuatu!",
  str_guide_warn_11500402 = "Pergi ke Lair untuk memulai tantangan. Selain Lumamber, pemain juga akan mendapatkan Talent Mastery EXP untuk meningkatkan Level Talent mereka dan mendapatkan Talent Mastery Point agar menjadi lebih kuat.",
  str_guide_warn_11500403 = "Di sinilah Anda dapat menemukan pencarian Lair Reward. Menyelesaikan misi juga akan memberi Anda Poin Penguasaan Bakat.",
  str_guide_warn_11500404 = "Habiskan Poin Penguasaan Bakat untuk membuka Keterampilan Penguasaan Bakat, Perlengkapan Caelestite Khusus, dan Relik untuk mempermudah Tantangan Sarang!",
  str_guide_warn_11500405 = "Setiap hari, Aurorian uji coba yang berbeda akan tersedia untuk digunakan dalam Lair Challenges.",
  str_guide_warn_11500406 = "Anda dapat menemukan informasi lebih lanjut tentang Lair di sini. Jangan ragu untuk menjelajahinya kapan saja.",
  str_guide_warn_11500601 = "Dapatkan EXP Penguasaan Bakat yang cukup untuk meningkatkan Level Bakat Anda dan dapatkan Poin Penguasaan Bakat.",
  str_guide_warn_11500602 = "Habiskan Poin Penguasaan Bakat untuk mengaktifkan Penguasaan Bakat seperti Perlengkapan Caelestite Khusus untuk meningkatkan tim Anda.",
  str_guide_warn_11500603 = "Setelah menggunakan Poin Penguasaan Bakat yang cukup, Relik yang kuat dapat muncul secara acak selama Tantangan Sarang.",
  str_guide_warn_11500604 = "Kalian bisa melengkapi Special Caelestite Gear di sini. Mereka memberikan keterampilan tambahan yang kuat selama tantangan.",
  str_guide_warn_11500605 = "Jika Anda ingin mengedit Penguasaan Bakat Anda, Anda dapat mengatur ulang Penguasaan Bakat yang diaktifkan dan Poin Penguasaan Bakat yang dibelanjakan tanpa biaya.",
  str_guide_warn_11500701 = "Ketuk di sini untuk melihat Aurorian di tim Anda.",
  str_guide_warn_11600101 = "Acara Terukir di Lautan telah dimulai! Bergabunglah dengan teman-teman baru dari Longzhou saat kami mencari harta karun yang hilang dan mengungkap rahasia misterius di The Homecoming!",
  str_guide_warn_11600102 = "Di Lost Ship At Sea, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11600103 = "Promissory Note Lin Guild yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menukarkan berbagai hadiah dari The Docks.",
  str_guide_warn_11600104 = "Selama Festival Musim Semi, penduduk Longzhou menyiapkan pesta mewah yang disebut Makan Malam Persatuan. Bantu Dantang menemukan resep untuk membuat hidangan lezat untuk mendapatkan berbagai hadiah, termasuk Lumamber!",
  str_guide_warn_11600105 = "Buku tamu anonim telah muncul di set. Secara bertahap akan diisi dengan komentar anonim. Baca pesan ini untuk mendapatkan skrip film baru!",
  str_guide_warn_11600106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11600107 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11600108 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11700101 = "Acara Fragmentary Vow telah dimulai! Mulailah petualangan dengan teman baru Anda dari Courier Union di Mooncrown Pilgrimage.",
  str_guide_warn_11700102 = "Dalam Feather Seal Crisis, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11700103 = "Bulu Langka yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat ditukar dengan berbagai hadiah di Courier Express.",
  str_guide_warn_11700104 = "Di Sweet Delivery, Anda dapat mengalami hidup bekerja di pos Serikat Kurir dan menyelesaikan krisis harapan terbaik Navigator yang tak ada habisnya pada saat yang sama!",
  str_guide_warn_11700105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11700106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11700107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11700201 = "Ini adalah informasi pesanan yang Anda terima saat ini. Ketuk avatar untuk beralih pesanan.",
  str_guide_warn_11700202 = "Ayo selesaikan dulu pesanan Lilica. Dia membutuhkan pakaian, roti, dan anggur.",
  str_guide_warn_11700203 = "Di sebelah kanan, Anda dapat menemukan daftar barang lengkap.",
  str_guide_warn_11700204 = "Ayo masukkan roti ke dalam paket!",
  str_guide_warn_11700205 = "Sambil mengetuk dan menahan untuk menyeret barang, Anda juga dapat mengetuk tombol untuk memutar (tombol R) dan membalik (tombol T).",
  str_guide_warn_117002051 = "Sambil mengetuk dan menahan untuk menyeret barang, Anda juga dapat mengetuk tombol untuk memutar dan membalik.",
  str_guide_warn_11700206 = "Setelah semua barang yang dipesan dimasukkan ke dalam paket, ingat untuk mengetuk tombol pengemasan untuk mengirimkannya. Jika tidak semua item telah dimasukkan ke dalam paket, progres penyelesaian pesanan akhir akan terpengaruh.",
  str_guide_warn_11700207 = "Ketuk di sini untuk menjeda pengemasan.",
  str_guide_warn_11700208 = "Sekarang setelah Anda mengetahui semua tentang proses alur kerja, mari lanjutkan pengepakan!",
  str_guide_warn_11800101 = "Acara Pengakuan Sebelum Gavel Strikes telah dimulai! Mulailah petualangan dengan semua orang di Hall of Justice selama Penerimaan Sepenuh Hati.",
  str_guide_warn_11800102 = "Di When the Flowers Wither, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11800103 = "Fragmen Plester yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menebus berbagai hadiah dari Koleksi Bukti.",
  str_guide_warn_11800104 = "Selama acara Love on Trial, Anda akan berperan sebagai asisten hakim, mendengarkan kasus yang ada dan menyelidiki kebenaran dengan anggota Divisi Percintaan.",
  str_guide_warn_11800105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11800106 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11800107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11800201 = "Tidak semua orang bisa bekerja di Hall of Justice. Saya pasti akan memanfaatkan kesempatan ini sebaik mungkin jika saya jadi Anda! Ketuk di sini untuk pergi ke Hall of Justice dan lihat kasus apa yang menunggu Anda.",
  str_guide_warn_11800202 = "Kasus dapat memiliki akhir yang berbeda tergantung pada bagaimana persidangan berjalan. Jika Anda mengalami kebuntuan saat menyelidiki, Anda dapat membuka Catatan Kasus dan memilih titik pemilihan cerita yang sesuai untuk membuat keputusan yang berbeda.",
  str_guide_warn_11800203 = "Anda pasti akan dihargai atas kerja keras Anda. Selesaikan cerita untuk membuka akhiran dan penuhi berbagai persyaratan untuk mengklaim lencana dan hadiah di sini!",
  str_guide_warn_11800204 = "Saya telah menuliskan semua detailnya di sini. Ingatlah untuk membacanya lagi jika masih ada yang belum Anda mengerti.",
  str_guide_warn_11800301 = "Wow! Anda sudah belajar bagaimana mengumpulkan bukti begitu cepat? Semua bukti ini akan mulai digunakan saat tiba waktunya untuk menyajikan bukti.",
  str_guide_warn_11800401 = "Itu benar. Saatnya untuk menyajikan bukti! Bukti yang telah Anda kumpulkan akan dicantumkan dalam daftar bukti. Jangan lupa ketuk untuk melihat informasi lebih detail.",
  str_guide_warn_11800402 = [[
Menyajikan bukti yang salah dapat memengaruhi Kompetensi Anda dan hasil persidangan!
Mari kita coba memilih bukti yang tepat sesuai dengan pertanyaan Angel. Ketuk di sini untuk menyerang balik!]],
  str_guide_warn_11800501 = "Buku Catatan Hakim adalah simbol identitas seorang hakim. Penasaran dengan isinya?",
  str_guide_warn_11800502 = "Oh! Bukti dan detail yang Anda kumpulkan dicatat di sini. Itu membuatnya sangat nyaman untuk memeriksa semuanya.",
  str_guide_warn_11800503 = "Penting juga untuk membina Rapport yang lebih kuat dengan kolega Anda karena Rapport antara Anda dan kolega Anda juga dapat memengaruhi arah persidangan. Semoga beruntung!",
  str_guide_warn_11800601 = "Biarkan saya memperkenalkan aturan dasar permainan! Anda perlu mengontrol karakter Anda, berjuang melalui semua tahapan sampai Anda mencapai bos terakhir — Gronkenstein Ruu!",
  str_guide_warn_11800602 = "Anda dapat mengetuk tombol ini untuk berganti karakter, tetapi semuanya persis sama dalam hal gameplay yang sebenarnya — jangan menilai itu!",
  str_guide_warn_11800603 = "Jika masih ada yang belum Anda pahami, Anda bisa melihat dokumentasinya di sini.",
  str_guide_warn_11800701 = "Tahapan akan terbuka secara bertahap seiring waktu. Mari kita coba tahap pertama!",
  str_guide_warn_11800702 = "Selama Anda menyelesaikan target pertama dari setiap tahap, Anda akan menyelesaikannya! Anda juga dapat pergi untuk semua target jika Anda mau!",
  str_guide_warn_11800703 = "Mari bersiap-siap untuk bergemuruh!",
  str_guide_warn_11800801 = "Ini dia! Anda harus membuat karakter Anda terus maju dan mencoba untuk tidak membiarkan Eclipsites menangkap Anda! Buatlah sampai ke sasaran!",
  str_guide_warn_11800802 = "Ada Eclipsite normal di depan! Raih momen yang tepat untuk melompat di atas kepalanya, lalu permainan akan berakhir untuk orang normal itu!",
  str_guide_warn_11800803 = "Sekarang! Ketuk tombol Lompat!",
  str_guide_warn_118008031 = "Sekarang! Ketuk tombol Lompat (T)!",
  str_guide_warn_11800804 = "Tidak buruk! Anda seorang gamer alami!",
  str_guide_warn_11800805 = "Selanjutnya, kita harus berurusan dengan Eclipsite yang terbang. Setelah Anda terpental, Anda dapat menyerang Eclipsite di posisi yang lebih tinggi menggunakan lompatan ganda!",
  str_guide_warn_11800806 = "Sekarang, ketuk Lompat!",
  str_guide_warn_11800807 = "Ketuk Lompat lagi untuk menggunakan serangan lompat ganda!",
  str_guide_warn_11800808 = "Anda sekarang telah secara resmi menguasai kontrol dasar permainan! Coba selesaikan tahap ini sendiri!",
  str_guide_warn_11800901 = "Navigator, seekor birdie kecil memberi tahu saya bahwa Anda telah mengeluh tentang tahap pertama yang terlalu mudah bagi Anda!",
  str_guide_warn_11800902 = "Yah, jangan khawatir—aku punya monster baru yang lebih sulit menunggumu! Eclipsites berkepala helm ini harus dilompati dua kali sebelum Anda dapat menghitungnya!",
  str_guide_warn_11800903 = "Ketuk Lompat dan singkirkan helm itu!",
  str_guide_warn_11800904 = "Ketuk Menyelam saat berada di udara untuk menukik ke bawah dengan cepat dan memusnahkan musuh di bawah!",
  str_guide_warn_118009041 = "Tekan Dive (R) saat berada di udara untuk menukik ke bawah dengan cepat dan memusnahkan musuh di bawah!",
  str_guide_warn_11800905 = "Tip: Menyelam tidak hanya bagus untuk menyerang musuh tetapi juga membuat Anda memantul lebih tinggi, sehingga Anda dapat menjangkau musuh jauh di atas langit!",
  str_guide_warn_11800906 = "Ini sedikit nasihat terakhir yang akan kuberikan padamu! Eclipsites berduri ini tidak bisa diinjak, jadi saat Anda melihatnya, hindari dengan melompat! Nah, semuanya terserah Anda sekarang, Navigator! Semoga beruntung!",
  str_guide_warn_11801001 = "Eheheheh! Akhirnya, saatnya bagi saya untuk menjadi pusat perhatian! Temui bos terakhir—Gronkenstein Ruu!",
  str_guide_warn_11801101 = "Ini adalah salah satu cangkang cintaku. Berjanjilah padaku kau tidak akan menggunakan Dive atau Double Jump untuk menghancurkannya. Kalau tidak, aku tidak akan bisa mengalahkanmu!",
  str_guide_warn_11801201 = "Astaga! Kamu benar-benar membelokkan cangkangku dan malah membuatnya mengenaiku!?",
  str_guide_warn_11801202 = "Aku hanya punya begitu banyak HP... Jika kau terus memukulku dengan peluru, aku akan... Hei, kenapa kau sangat ahli dalam hal ini, Navigator!? Baiklah kalau begitu! Ayo!",
  str_guide_warn_11900101 = "Acara Phantom of the Fire telah dimulai! Bersiaplah untuk menyelidiki kasus misterius dan jelajahi kebenaran di baliknya bersama teman-teman Anda di Umbraton in Manhunt: The Blue Flame!",
  str_guide_warn_11900102 = "Dalam Dark Alley Encounters, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_11900103 = "Catatan Kasus yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menukarkan berbagai hadiah dari Pencarian & Penyitaan.",
  str_guide_warn_11900104 = "Dalam mode misteri Coretan Tengah Malam, kita akan menjelajahi rahasia panti asuhan bersama anak muda Hati!",
  str_guide_warn_11900105 = "Crash & Burn kembali untuk waktu yang terbatas! Bersiaplah untuk mengalami gameplay unik ini!",
  str_guide_warn_11900106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_11900107 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_11900108 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_11900201 = "Selamat datang di Coretan Tengah Malam! Mari kita tinjau kembali pengalaman masa lalu kita di panti asuhan bersama!",
  str_guide_warn_11900202 = "Ketuk Pick Up Crayon untuk memulai!",
  str_guide_warn_11900203 = "Jika Anda sudah memulai petualangan menyusuri jalan kenangan, ketuk di sini untuk melanjutkan perjalanan Anda!",
  str_guide_warn_11900204 = "Misi dan hadiah akan ditampilkan di album, dan Anda juga dapat melihat akhir yang telah Anda capai!",
  str_guide_warn_11900205 = "Jika masih ada yang belum kamu pahami, kamu bisa cek informasinya di sini.",
  str_guide_warn_11900301 = "Ini adalah peta panti asuhan. Kita harus menjelajah ke mana-mana untuk menemukan inspirasi!",
  str_guide_warn_11900302 = "Inspirasi yang Anda temukan akan ditampilkan di sini. Mereka akan berguna nanti!",
  str_guide_warn_11900303 = "Ayo sapa Miss Childminder!",
  str_guide_warn_11900304 = "Ayo tanya Nona Childminder tentang tempat ini!",
  str_guide_warn_11900401 = "Apakah Anda siap untuk berbicara dengan Miss Childminder?",
  str_guide_warn_11900402 = "Berikut adalah daftar pertanyaan yang dapat Anda ajukan. Beberapa di antaranya bisa ditanyakan langsung, sementara yang lain hanya bisa ditanyakan setelah Anda menemukan inspirasi tertentu!",
  str_guide_warn_11900403 = "Ajukan pertanyaan padanya tentang tempat ini!",
  str_guide_warn_11900404 = "Teruslah bertanya sambil menjelajah untuk menemukan inspirasi! Anda dapat mengajukan lebih banyak pertanyaan setelah menemukan lebih banyak inspirasi!",
  str_guide_warn_11900501 = "Di sini sangat berantakan. Mari selidiki semuanya dengan cermat!",
  str_guide_warn_11900502 = "Terlihat di sini bahwa ada banyak benda mencurigakan di ruangan ini!",
  str_guide_warn_11900503 = "Sepertinya tidak ada petunjuk. Mari kita fokus mengamati dulu.",
  str_guide_warn_11900504 = "Ada sepasang sarung tangan aneh di sini. Mendekatlah dan periksa!",
  str_guide_warn_11900601 = "Mari kita telusuri inspirasi yang telah kita temukan dan rekap peristiwa hari ini terlebih dahulu!",
  str_guide_warn_11900602 = "Untuk memecahkan misteri ini, kita membutuhkan tiga inspirasi untuk mendapatkan jawabannya.",
  str_guide_warn_11900603 = "Ini semua inspirasi yang Anda miliki. Anda harus memilih yang benar!",
  str_guide_warn_11900604 = "Pertama, tentang tempat ini... Sepertinya rumah yang penuh cinta dan kasih sayang?",
  str_guide_warn_11900605 = "Setelah itu, terlihat jelas bahwa anak-anak tinggal bersama kami di sini. Ada banyak anak di panti asuhan!",
  str_guide_warn_11900606 = "Akhirnya, apakah kita baik atau buruk? Meskipun beberapa dari kita baik, tampaknya ada juga beberapa orang jahat di sini... Kita harus mengidentifikasi mereka semua dengan hati-hati.",
  str_guide_warn_11900607 = "Cobalah memilah-milah inspirasi Anda!",
  str_guide_warn_11900608 = "Kesuksesan! Jadi seperti itulah situasi di panti asuhan!",
