  ["str_guide_circle_jianta-10-BOSS_LbT"] = "Tips Khusus",
  ["str_guide_circle_jianta-15-BOSS_Lb"] = "Dulunya adalah seorang Aurorian dari Lumopolis... Hati-hati dengan teriakannya!",
  ["str_guide_circle_jianta-15-BOSS_LbT"] = "Gertzurde",
  ["str_guide_circle_jianta-15-BOSS_Rb"] = "Ia menurunkan ATK musuhnya dan juga membakar debuff musuhnya untuk menimbulkan damage!",
  ["str_guide_circle_jianta-15-BOSS_RbT"] = "Tips Khusus",
  ["str_guide_circle_jianta-20-BOSS_Lb"] = "Variasi dari Siphorb yang sangat membenci Aurorian.",
  ["str_guide_circle_jianta-20-BOSS_LbT"] = "Solmorph",
  ["str_guide_circle_jianta-20-BOSS_Rb"] = "Meluncurkan serangan jarak jauh yang menarik musuhnya ke arah dirinya sendiri. Waspadalah!",
  ["str_guide_circle_jianta-20-BOSS_RbT"] = "Jarak Serang",
  ["str_guide_circle_11-7BOSS_Lb"] = "Dia bisa mengumpulkan Bruise ketika menerima damage saat siang hari, lalu mengonversinya menjadi HP saat malam hari, serta berubah menjadi Eclipsite yang jauh lebih kuat karena mampu menimbulkan damage pada semua musuh di layar.",
  ["str_guide_circle_11-7BOSS_LbT"] = "Dreamwalker",
  ["str_guide_circle_11-7BOSS_Rb"] = "Strategi Melawan",
  ["str_guide_circle_11-7BOSS_RbT"] = "Menimbulkan damage besar saat malam serta memiliki kemampuan kontrol untuk menyingkirkan kawanan monster tersebut dengan efektif.",
  ["str_guide_circle_air1-1_Lt"] = "Collector adalah instalasi yang sangat penting dan harus dilindungi dengan baik.",
  ["str_guide_circle_air1-1_LtT"] = "Collector",
  ["str_guide_circle_air1-1_Lb"] = "Collector memiliki 3 skill dan bisa menahan serangan biasa dari musuh.",
  ["str_guide_circle_air1-1_LbT"] = "Skill Tambahan",
  ["str_guide_circle_air1-1_Rb"] = "Lindungi Collector, bunuh semua Eclipsite, dan pastikan keamanan dari Core!",
  ["str_guide_circle_air1-1_RbT"] = "Lindungi Collector",
  ["str_guide_circle_air1-2_Lb"] = "Gunakan Collector Energy untuk memakai skill. Hati-hati jangan sampai dipakai berlebihan!",
  ["str_guide_circle_air1-2_LbT"] = "Collector Energy",
  ["str_guide_circle_ex2-1_Lt"] = "Bom sangat ringan yang bisa didorong dengan skill pendorong.",
  ["str_guide_circle_ex2-1_LtT"] = "Hydraulic Bomb",
  ["str_guide_circle_ex2-1_Lb"] = "Hydraulic Bomb akan meledak setelah mengenai target pertama setelah didorong, menimbulkan damage besar!",
  ["str_guide_circle_ex2-1_LbT"] = "Explosive Damage",
  ["str_guide_circle_N1_1-1_Lb"] = "Tidak bisa bertarung, tapi bisa menempel pada Eclipsite lain untuk melindungi dan meningkatkan attribute miliknya.",
  ["str_guide_circle_N1_1-1_LbT"] = "Lurker",
  ["str_guide_circle_N1_1-1_Rb"] = "Singkirkan monster itu sebelum menempel.",
  ["str_guide_circle_N1_1-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N1_1-8_Lb"] = "Melancarkan Large Area Damage.",
  ["str_guide_circle_N1_1-8_LbT"] = "Dawn",
  ["str_guide_circle_N1_1-8_Rb"] = "Memanggil Dawn Sprite, HP Dawn pulih saat Dawn Sprite berada di dekatnya.",
  ["str_guide_circle_N1_1-8_RbT"] = "Tips penting",
  ["str_guide_circle_N1_2-1_Lb"] = "Melancarkan Large Area Damage.",
  ["str_guide_circle_N1_2-1_LbT"] = "Eve",
  ["str_guide_circle_N1_2-1_Rb"] = "Eve membuat shield untuk dirinya sendiri untuk menangkis damage.",
  ["str_guide_circle_N1_2-1_RbT"] = "Tips penting",
  ["str_guide_circle_N1_2-2_Lb"] = "Rasa sakit Eve membuatnya tidak bisa mengambil tindakan untuk sementara.",
  ["str_guide_circle_N1_2-2_LbT"] = "Eve",
  ["str_guide_circle_N1_2-2_Rb"] = "Lindungi Eve dari serangan Eclipsite.",
  ["str_guide_circle_N1_2-2_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N1_2-3_Lb"] = "Eve tidak akan diserang Eclipsite dan terus memulihkan HP sekutu di dekatnya.",
  ["str_guide_circle_N1_2-3_LbT"] = "Eve",
  ["str_guide_circle_N1_2-3_Rb"] = "Tangkis serangan Eclipsite dengan bantuan Eve dan raih kemenangan.",
  ["str_guide_circle_N1_2-3_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N3_1-1_LbT"] = "Fallen Knight",
  ["str_guide_circle_N3_1-1_Lb"] = "Menyerang menurut aturan langkah kuda dalam catur.",
  ["str_guide_circle_N3_1-1_RbT"] = "Tips penting",
  ["str_guide_circle_N3_1-1_Rb"] = "Jangan berdiri di lokasi yang bisa dijadikan tempat pendaratan Fallen Knight. Kalau tidak, kamu akan terkena Stun.",
  ["str_guide_circle_N3_1-3_LbT"] = "Enraged Rook",
  ["str_guide_circle_N3_1-3_Lb"] = "Menyerang menurut aturan langkah benteng dalam catur. Menyerang secara horizontal atau vertikal.",
  ["str_guide_circle_N3_1-3_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N3_1-3_Rb"] = "Coba gunakan rintangan untuk melancarkan serangan melingkar terhadap Enraged Rook.",
  ["str_guide_circle_N3_1-5_LbT"] = "Eclipse Bishop",
  ["str_guide_circle_N3_1-5_Lb"] = "Bergerak diagonal menurut aturan langkah gajah dalam catur. Menyerang secara horizontal atau vertikal.",
  ["str_guide_circle_N3_1-5_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N3_1-5_Rb"] = "Gunakan rintangan saat mencoba menghindari serangan Eclipse Bishop.",
  ["str_guide_circle_N3_1-7_LtT"] = "Deceptive Queen",
  ["str_guide_circle_N3_1-7_Lt"] = "Menyerang menurut aturan langkah ratu dalam catur dan menimbulkan damage besar kepada target yang berada dalam radius jangkauannya. Jika target berada di luar jangkauan, dia akan menunggu hingga mendapatkan peluang untuk menyerang.",
  ["str_guide_circle_N3_1-7_RtT"] = "Tips penting",
  ["str_guide_circle_N3_1-7_Rt"] = "Pastikan kamu tidak berada dalam jangkauan peringatan dini Deceptive Queen. Kalau tidak, mungkin saja kamu akan terkena damage besar.",
  ["str_guide_circle_N3_1-9_LtT"] = "Lost Pawn",
  ["str_guide_circle_N3_1-9_Lt"] = "Bergerak maju setiap putaran sambil melancarkan serangan seraya melompat. Setelah mencapai tepi kiri bawah board, dia akan dipromosikan ke posisi pion sesuai urutan berikut: Benteng, Kuda, Gajah, Ratu.",
  ["str_guide_circle_N3_1-9_RtT"] = "Strategi Melawan",
  ["str_guide_circle_N3_1-9_Rt"] = "Hindari serangan Lost Pawn - CHAMP dan kalahkan sebelum dia dipromosikan.",
  ["str_guide_circle_N3_1-20_LbT"] = "Desolate Monarch",
  ["str_guide_circle_N3_1-20_Lb"] = "Pengendali monster catur. Seorang ahli strategi yang sangat lihai memerintah pasukannya dan memaksa musuh untuk pasrah.",
  ["str_guide_circle_N3_1-20_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N3_1-20_Rb"] = "Dia memaksa board bergerak turun satu tile setiap putaran sehingga akan mempercepat transformasi Lost Pawn miliknya. Singkirkan semua Lost Pawn di board secepat mungkin dan perhatikan posisi setiap bidak dalam setiap putaran.",
  ["str_guide_circle_N5_1-3_LtT"] = "Chasm",
  ["str_guide_circle_N5_1-3_Lt"] = "Setelah beberapa putaran, ia melepaskan energi batinnya untuk menghancurkan diri sendiri dan menghancurkan medan.",
  ["str_guide_circle_N5_1-3_RtT"] = "Tile Rusak",
  ["str_guide_circle_N5_1-3_Rt"] = "Tile yang pecah tidak dapat digunakan oleh Aurorian.",
  ["str_guide_circle_N5_1-3_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N5_1-3_Rb"] = "Kalahkan Chasm sebelum meledak!",
  ["str_guide_circle_N5_1-10_LbT"] = "Hylingerr",
  ["str_guide_circle_N5_1-10_Lb"] = "Monster raksasa yang licik sekaligus kuat. Menimbulkan damage parah pada target dalam jangkauan dan memiliki kemampuan untuk merekam posisi target.",
  ["str_guide_circle_N5_1-10_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N5_1-10_Rb"] = "Monster ini relatif besar. Perhatikan posisimu untuk menghindari sebagian besar damage yang dia lancarkan.",
  ["str_guide_circle_N6_1-10_LtT"] = "Mirren Gautier",
  ["str_guide_circle_N6_1-10_Lt"] = "Kekuatan sang mantan bangsawan ini bertambah seiring dengan makin dalam kebenciannya terhadap Lumopolis…",
  ["str_guide_circle_N6_1-10_RtT"] = "Sembunyikan",
  ["str_guide_circle_N6_1-10_Rt"] = "Bisa bersembunyi saat berada di tile rusak dan menjadi kebal terhadap damage dari Normal Attack dan skill ketika satu tile dipilih.",
  ["str_guide_circle_N6_1-10_LbT"] = "Grudge",
  ["str_guide_circle_N6_1-10_Lb"] = "Bisa berteleportasi beberapa kali dan menghancurkan tile di medan tempur saat musuh tidak berada dalam jangkauan serangan.",
  ["str_guide_circle_N6_1-10_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N6_1-10_Rb"] = "Lenyapkan tile rusak sebelum menyerang!",
  ["str_guide_circle_N6_1-1_LtT"] = "Mantleworm",
  ["str_guide_circle_N6_1-1_Lt"] = "Sesosok Eclipsite yang pernah menghuni kedalaman Secret Territory ini unggul dalam melancarkan serangan dari bawah tanah. Konon, ia juga mampu menggali lorong bawah tanah untuk Eclipsite lainnya.",
  ["str_guide_circle_N6_1-1_RtT"] = "Catatan",
  ["str_guide_circle_N6_1-1_Rt"] = "Unggul dalam memanfaatkan medan yang rusak dan memiliki kemampuan untuk menimbulkan damage berat pada unit di sekitar Tile Rusak.",
  ["str_guide_circle_N6_1-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N6_1-1_Rb"] = "Kontrol jumlah tile yang hancur di medan tempur dan perhatikan posisimu!",
  ["str_guide_circle_N7_1-10_LtT"] = "Maude Solus",
  ["str_guide_circle_N7_1-10_Lt"] = "Mengalami transformasi sementara yang berbahaya tanpa berpikir panjang untuk memperoleh kekuatan yang seluruhnya baru.",
  ["str_guide_circle_N7_1-10_RtT"] = "Solus Puppet",
  ["str_guide_circle_N7_1-10_Rt"] = "Bisa terus-menerus memanggil Eclipsite untuk membantu dalam pertarungan.",
  ["str_guide_circle_N7_1-10_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N7_1-10_Lb"] = "Cegah Maude agar tidak memanggil Eclipsite dan langsung serang dia!",
  ["str_guide_circle_N7_1-4_LbT"] = "Tetap waspada!",
  ["str_guide_circle_N7_1-4_Lb"] = "Eclipsite yang bermutasi setelah menggunakan \"enhancer\" tampaknya benar-benar berbeda dari yang biasa kita hadapi! Tolong hati-hati!",
  ["str_guide_circle_N9_1-3_LbT"] = "???",
  ["str_guide_circle_N9_1-3_Lb"] = "Eclipsite misterius yang asalnya tidak diketahui dan kehadirannya tampaknya tidak sesuai dengan kenyataan yang kau lihat.",
  ["str_guide_circle_N9_1-3_RbT"] = "Monster Trait",
  ["str_guide_circle_N9_1-3_Rb"] = "Saat tidak berada di Aurora Time, mendapatkan pengurangan damage yang signifikan.",
  ["str_guide_circle_N9_1-3_LtT"] = "Strategi Melawan",
  ["str_guide_circle_N9_1-3_Lt"] = "Serang monster selama Aurora Time berlangsung!",
  ["str_guide_circle_N9_1-10_LbT"] = "Fearmonger",
  ["str_guide_circle_N9_1-10_Lb"] = "Debu telah mereda dan identitas musuh asing yang familier akan segera terungkap. Saatnya untuk membuktikan tekad.",
  ["str_guide_circle_N9_1-10_RbT"] = "Monster Trait",
  ["str_guide_circle_N9_1-10_Rb"] = "Saat tidak berada di Aurora Time, mendapatkan pengurangan damage yang signifikan. Mampu memanggil minion untuk membantu pertempuran.",
  ["str_guide_circle_N9_1-10_LtT"] = "Strategi Melawan",
  ["str_guide_circle_N9_1-10_Lt"] = "Singkirkan minion dan serang Fearmonger sesering mungkin selama Aurora Time!",
  ["str_guide_circle_N11_1-3_LtT"] = "Jammer I",
  ["str_guide_circle_N11_1-3_Lt"] = "Jebakan misterius dari Lost City. Tampaknya menjadi prototipe awal dari Jammer.",
  ["str_guide_circle_N11_1-3_RtT"] = "Karakteristik Jebakan",
  ["str_guide_circle_N11_1-3_Rt"] = "Dengan kemampuannya mengganggu area sekitarnya, Aurorian menerima damage saat bergerak di sekitarnya.",
  ["str_guide_circle_N11_1-3_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N11_1-3_Lb"] = "Berhati-hatilah untuk tidak mendekati Jammer saat bergerak!",
  ["str_guide_circle_N11_1-12_LbT"] = "Valencia",
  ["str_guide_circle_N11_1-12_Lb"] = "Penduduk kota yang hilang dan keturunan penjelajah Illumina—Seamus.",
  ["str_guide_circle_N11_1-12_RbT"] = "Awas!",
  ["str_guide_circle_N11_1-12_Rb"] = "Valencia mampu memanggil dan mengendalikan jebakan yang kuat untuk membantunya bertempur. Hati-hati dengan jebakannya di luar sana!",
  ["str_guide_circle_N12_1-1_LbT"] = "Kittypus",
  ["str_guide_circle_N12_1-1_Lb"] = "Teman spesial Gretel. Ia menyerupai kucing dengan banyak kaki... Ia lucu, tetapi entah kenapa sedikit mengganggu.",
  ["str_guide_circle_N12_1-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N12_1-1_Rb"] = "Tentaclaw mampu memindahkan damage yang dia terima ke tubuh utama. Kemampuan ini dapat digunakan untuk melawan monster.",
  ["str_guide_circle_N12_1-2_LbT"] = "Ironstomp",
  ["str_guide_circle_N12_1-2_Lb"] = "Teman spesial Gretel. Ia memiliki sepasang kaki yang sangat kuat yang dapat mengusir siapapun musuhnya.",
  ["str_guide_circle_N12_1-2_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N12_1-2_Rb"] = "Ironstomp adalah penghancur tile yang terampil. Bawa serta Aurorian pengonversi tile untuk melawannya.",
  ["str_guide_circle_N12_1-3_LbT"] = "Basilisk",
  ["str_guide_circle_N12_1-3_Lb"] = "Teman spesial Gretel. Ia menyenangkan dan energik, serta sangat menikmati pertarungan melawan segerombolan musuh.",
  ["str_guide_circle_N12_1-3_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N12_1-3_Rb"] = "Di balik kulit kasar Basilisk ada hati yang lembut. Skill kontrol bisa bekerja dengan baik untuk melawannya.",
  ["str_guide_circle_N12_1-4_LbT"] = "Spikeyhog",
  ["str_guide_circle_N12_1-4_Lb"] = "Teman spesial Gretel. Biasanya tenang dan kalem, tetapi dikenal mengamuk dalam pertempuran. Dekati sambil waspada.",
  ["str_guide_circle_N12_1-4_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N12_1-4_Rb"] = "Tubuh Spikeyhog dipenuhi duri. Aurorian sebaiknya menjaga jarak.",
  ["str_guide_circle_N13_1-1_LbT"] = "Sword of the Underworld",
  ["str_guide_circle_N13_1-1_Lb"] = "Mantan kepala Wisp yang berdedikasi untuk memerangi penjajah Cloud Island.",
  ["str_guide_circle_N13_1-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N13_1-1_Rb"] = "Sword of the Underworld akan membuat pilihan taktis yang berbeda berdasarkan jaraknya dari Aurorian. Jaga jarak untuk mendapatkan kemampuan pemulihan dan untuk menangani serangannya dengan lebih baik.",
  ["str_guide_circle_N14_1-1_LbT"] = "Nagi - Fury Blade",
  ["str_guide_circle_N14_1-1_Lb"] = "Nagi yang gila akan menyerang siapa saja yang dia anggap sebagai penyusup.",
  ["str_guide_circle_N14_1-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N14_1-1_Rb"] = "Amati Nagi - Rentetan serangan Fury Blade untuk menghindari Lethal Damage dan Counterattack saat ada kesempatan.",
  ["str_guide_circle_N13_1-12_LbT"] = "Fujikumo Nobutora",
  ["str_guide_circle_N13_1-12_Lb"] = "Seorang tiran yang datang dari pulau Far East lain untuk memerintah Cloud Island, dan dia akan melakukan apa saja untuk menyatakan kedaulatan atasnya.",
  ["str_guide_circle_N13_1-12_RbT"] = "Awas!",
  ["str_guide_circle_N13_1-12_Rb"] = "Fujikumo Nobutora dapat memanggil banyak hantu untuk membantunya bertempur.",
  ["str_guide_circle_N13_1-12_LtT"] = "Strategi Melawan",
  ["str_guide_circle_N13_1-12_Lt"] = "Singkirkan semua hantu di medan tempur tepat waktu.",
  ["str_guide_circle_N14_1-12_LbT"] = "Fujikumo Nobutora - Devour",
  ["str_guide_circle_N14_1-12_Lb"] = "Karena obsesinya, ia berubah menjadi pria yang mengerikan dan bersumpah untuk melenyapkan semua yang melawan.",
  ["str_guide_circle_N14_1-12_RbT"] = "Peringatan!",
  ["str_guide_circle_N14_1-12_Rb"] = "Fujikumo Nobutora - Devour akan mengeluarkan skill yang berbeda berdasarkan posisi Aurorian.",
  ["str_guide_circle_N14_1-12_LtT"] = "Strategi Melawan",
  ["str_guide_circle_N14_1-12_Lt"] = "Saat dalam pertempuran, ingatlah untuk memposisikan diri dengan hati-hati dan melakukan serangan balik dengan tepat.",
  ["str_guide_circle_N13_1-2_LbT"] = "Hantu",
  ["str_guide_circle_N13_1-2_Lb"] = "Monster Far East spesial yang disebut \"hidup segan mati tak mau\" dan sangat memusuhi yang hidup.",
  ["str_guide_circle_N13_1-2_RbT"] = "Monster Trait",
  ["str_guide_circle_N13_1-2_Rb"] = "Kemampuan bertarung mereka mungkin tidak menakutkan, tetapi jumlah mereka menggertak.",
  str_guide_fail_1 = "Memperkuat Aurorian",
  str_guide_fail_2 = "Menaikkan level Aurorian dan melakukan Ascending pada mereka adalah cara bagus untuk memperkuat kemampuan Aurorian",
  str_guide_fail_3 = "Aurorian yang bisa di-upgrade:",
  str_guide_fail_4 = "Mendapatkan Material untuk Memperkuat",
  str_guide_fail_5 = "Dapatkan Aurorian EXP material dan Breakthrough material dengan cara-cara berikut",
  str_guide_fail_6 = "Didapatkan dari: Forgotten Snow Resource Stages dan Main Stage",
  str_guide_fail_7 = "Ketuk di mana saja untuk melewatkan",
  str_guide_warn_level_speed = "PERINGATAN Harus menaikkan level!",
  str_guide_fail_8 = "Stage gagal",
  str_guide_warn_40096 = "Ketuk di sini",
  str_guide_fail_9 = "Kenali dan pahami Chess Piece Skill",
  str_guide_fail_10 = "Pelajari karakteristik setiap bidak catur dan kerahkan potensi terbaiknya.",
  str_guide_fail_11 = "Sesuaikan strategi pertempuran",
  str_guide_fail_12 = "Setiap musuh bergerak berdasarkan pola gerakan yang tetap. Sesuaikan strategi pertarunganmu.",
  ["str_guide_circle_N17_1-14_LtT"] = "Claudia",
  ["str_guide_circle_N17_1-14_Lt"] = "AI di markas bawah tanah Eraveil yang telah menjaga markas selama ribuan tahun dan bertanggung jawab memusnahkan seluruh musuh yang menyerang.",
  ["str_guide_circle_N17_1-14_RbT"] = "Monster Trait",
  ["str_guide_circle_N17_1-14_Rb"] = "Kebal sepenuhnya terhadap Normal Attack saat berdiri di atas pijakan atau berada di atas Asher, langsung melompat ke pijakan lain dalam jangkauan 2 klaster begitu pijakan yang kauinjak hancur.",
  ["str_guide_circle_N17_1-14_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N17_1-14_Lb"] = "Gunakan Sniper untuk melancarkan hantaman langsung pada Claudia. Hati-hati, jangan sampai pijakannya hancur.",
  ["str_guide_circle_N17_2-14_LtT"] = "Asher",
  ["str_guide_circle_N17_2-14_Lt"] = "AI di markas bawah tanah Eraveil yang tampak besar dan berat itu adalah teman Claudia.",
  ["str_guide_circle_N17_2-14_RbT"] = "Monster Trait",
  ["str_guide_circle_N17_2-14_Rb"] = "Menunjukkan Trait Immortality dan akan langsung bangkit begitu ditumbangkan, tetapi semakin sering ditumbangkan, semakin sedikit HP yang dipulihkan.",
  ["str_guide_circle_N17_2-14_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N17_2-14_Lb"] = "Kelilingi pelindung kuat ini dan kalahkan Claudia sesegera mungkin.",
  ["str_guide_circle_N18_1-12_LtT"] = "Minos",
  ["str_guide_circle_N18_1-12_Lt"] = "Kepala pelayan unggulan Andersen yang tak akan membiarkan adanya noda, sampah, atau hama.",
  ["str_guide_circle_N18_1-12_RtT"] = "Monster Trait",
  ["str_guide_circle_N18_1-12_Rt"] = "Minos akan beralih antara Mortal State dan Minotaur State berdasarkan tumpukan Mark. Mereset semua tile yang ia lewati menjadi Enhanced Tile atau Weakened Tile berdasarkan State yang sedang aktif.",
  ["str_guide_circle_N18_1-12_RbT"] = "Peringatan!",
  ["str_guide_circle_N18_1-12_Rb"] = "Sebagian besar serangan Minos menjadi lebih kuat seiring meningkatnya jumlah tumpukan Mark miliknya. Semakin banyak tumpukan Mark yang ia miliki dan semakin banyak Enhanced Tile di medan tempur, semakin berbahaya pula serangannya.",
  ["str_guide_circle_N18_1-1_LtT"] = "Weakened Tile",
  ["str_guide_circle_N18_1-1_Lt"] = "Tile khusus yang berlawanan dengan Enhanced Tile ini dapat mengurangi damage yang ditimbulkan oleh koneksi pemain.",
  ["str_guide_circle_N18_1-1_RbT"] = "Karakteristik",
  ["str_guide_circle_N18_1-1_Rb"] = "Aurorian yang melewati ini akan mendapatkan debuff pengurangan damage koneksi 2 kali lipat dibandingkan Tile normal.",
  ["str_guide_circle_N20_1-12_LtT"] = "Penjaga Inti",
  ["str_guide_circle_N20_1-12_Lt"] = "Penjaga raksasa yang melindungi inti energi kapal. Itu akan bangun dan bertarung ketika Core berada di bawah ancaman.",
  ["str_guide_circle_N20_1-12_LbT"] = "Karakteristik Tempat",
  ["str_guide_circle_N20_1-12_Lb"] = "Saat Penjaga Inti terjaga, ia akan memutar sisi kubus ajaib menjauh dari pemain di akhir setiap putaran, mengubah distribusi monster di lapangan.",
  ["str_guide_circle_N20_1-12_RbT"] = "Enemy Weaknesses",
  ["str_guide_circle_N20_1-12_Rb"] = "Modul Freeze adalah kelemahan Guardian. Mengalahkan Freeze Module akan melumpuhkan Core Guardian selama 1 ronde dan membuatnya lebih mudah terluka.",
  str_guide_warn_5193011 = "Karakter Kolaborasi P5R memasuki pertempuran dengan Keterampilan Khusus mereka.",
  str_guide_warn_5193012 = "Ketuk di sini untuk melihat Deskripsi Keterampilan.",
  str_guide_warn_5193013 = "Luncurkan Keahlian Khusus dan tangani musuh-musuh ini dalam sekali jalan.",
  ["str_guide_circle_N22_1-10_LtT"] = "Casta",
  ["str_guide_circle_N22_1-10_Lt"] = "Terlihat menyendiri, tapi sebenarnya sangat bertanggung jawab. Bekerja sama dengan Pollux untuk membentuk duo tentara bayaran yang dijuluki \"Darah Raven\" untuk membela anak-anak yang tinggal di gereja dengan lebih baik.",
  ["str_guide_circle_N22_1-10_RbT"] = "Monster Trait",
  ["str_guide_circle_N22_1-10_Rb"] = "Meluncurkan serangan keterampilan yang berbeda sesuai dengan posisi sekutu; dapat melawan keterampilan aktif sekutu.",
  ["str_guide_circle_N22_1-10_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N22_1-10_Lb"] = "Mengawasi posisi relatif kedua sisi; mengontrol frekuensi melepaskan keterampilan aktif.",
  ["str_guide_circle_sailing_1-1_LtT"] = "gerbang cacing",
  ["str_guide_circle_sailing_1-1_Lt"] = "Meski tidak jelas bagaimana cara kerjanya, Eclipsites akan terus muncul darinya. Pertempuran mungkin akan menjadi sangat sulit jika tidak ditangani sesegera mungkin.",
  ["str_guide_circle_sailing_1-1_RbT"] = "Karakteristik",
  ["str_guide_circle_sailing_1-1_Rb"] = "Jika Wormgate dibuka, Eclipsites akan dipanggil di awal ronde berikutnya.",
  ["str_guide_circle_sailing_1-1_RtT"] = "Peringatan!",
  ["str_guide_circle_sailing_1-1_Rt"] = "Jika Eclipsite berdiri di atas Wormgate di awal ronde, Wormgate tidak akan memanggil Eclipsites baru di ronde ini.",
  ["str_guide_circle_sailing_2-1_LtT"] = "Halo Batu",
  ["str_guide_circle_sailing_2-1_Lt"] = "Batu dengan Lumina yang tidak diketahui, biasanya ada di reruntuhan, dikabarkan akan mengubah Lumina di sekitar mereka.",
  ["str_guide_circle_sailing_2-1_RbT"] = "Karakteristik",
  ["str_guide_circle_sailing_2-1_Rb"] = "Di awal setiap putaran pemain, Halo Stone mengubah semua ubin dari elemen yang berbeda dalam rentang tertentu menjadi elemen yang sama dengan dirinya sendiri.",
  ["str_guide_circle_sailing_2-1_RtT"] = "Strategy",
  ["str_guide_circle_sailing_2-1_Rt"] = "Elemen Halo Stone akan selalu sama dengan elemen ubinnya. Sekutu kita dapat menggunakan ini untuk mengambil keuntungan dalam pertempuran.",
  ["str_guide_circle_sailing_2-2_RbT"] = "Peringatan!",
  ["str_guide_circle_sailing_2-2_Rb"] = "Jika ubin di bawah Batu Halo menjadi ubin berwarna, Batu Halo akan dihancurkan.",
  ["str_guide_circle_sailing_2-3_LtT"] = "Skill Banning Stele",
  ["str_guide_circle_sailing_2-3_Lt"] = "Prasasti pendek nan misterius yang ditemukan di reruntuhan tertentu. Mantra yang terukir di atasnya memberikan efek penghambat tertentu kepada penyerang.",
  ["str_guide_circle_sailing_2-3_RbT"] = "Karakteristik",
  ["str_guide_circle_sailing_2-3_Rb"] = "Membungkam semua Aurorian dalam jarak tertentu, membuat mereka tidak dapat menggunakan skill aktif.",
  ["str_guide_circle_sailing_2-4_LtT"] = "Strategy",
  ["str_guide_circle_sailing_2-4_Lt"] = "Gunakan skill chain combo atau skill aktif yang memberikan damage area untuk memberikan damage pada Skill Banning Steles. Mereka akan pecah setelah menerima sejumlah kerusakan.",
  ["str_guide_circle_N22_2-1_LtT"] = "Monster Trait",
  ["str_guide_circle_N22_2-1_Lt"] = "Itu dapat menggunakan menara untuk memberikan kerusakan terus-menerus pada musuh dan mengusir musuh yang datang terlalu dekat dengannya. Penjaga akan memperkuat dirinya sendiri ketika merasakan ancaman besar.",
  ["str_guide_circle_N22_2-1_RtT"] = "Strategi Melawan",
  ["str_guide_circle_N22_2-1_Rt"] = "Self-Propelled Cannon dapat memberikan kerusakan pada musuh yang sama beberapa kali dalam putaran yang sama, tetapi pemain tidak perlu menghindari setiap pukulan karena tidak memberikan banyak kerusakan pada setiap pukulan.",
  ["str_guide_circle_N22_2-1_RbT"] = "Meriam Self-Propelled",
  ["str_guide_circle_N22_2-1_Rb"] = "Penjaga yang kuat mampu berpatroli sendiri. Baik meriam utama dan bahu sangat kuat. Hanya satu penjaga seperti itu yang dapat menyebabkan kerusakan besar.",
  ["str_guide_circle_N23_1-14_LtT"] = "Astor",
  ["str_guide_circle_N23_1-14_Lt"] = "Roh wanita yang berkeliaran tanpa tuan atau keinginannya sendiri; semua yang tersisa adalah permusuhan yang kuat terhadap yang hidup. Melalui ritual jahat, roh ini dapat digabungkan dengan Darkflow untuk menciptakan entitas supernatural yang kuat.",
  ["str_guide_circle_N23_1-14_RtT"] = "Monster Trait",
  ["str_guide_circle_N23_1-14_Rt"] = "Mengamuk melalui area yang ditentukan dan menyerap energi Lilin Maut untuk memperkuat dirinya sendiri.",
  ["str_guide_circle_N23_1-14_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N23_1-14_Rb"] = "Padamkan Lilin Maut untuk menjaga jarak dari Astor.",
  ["str_guide_circle_13-14_LtT"] = "Diavola",
  ["str_guide_circle_13-14_Lt"] = "Bagian luar tubuh bunga dijaga ketat oleh dedaunan yang keras, tetapi keterampilan Penembak Jitu dapat memberikan kerusakan yang mematikan pada bunga dan memperlihatkan kelemahannya.",
  ["str_guide_circle_13-14_RtT"] = "Monster Trait",
  ["str_guide_circle_13-14_Rt"] = "Saat terbangun, Diavola membalas setiap serangan normal yang dilakukan oleh Aurorian dan menimbulkan 1 tumpukan Toxin pada mereka.",
  ["str_guide_circle_13-14_RbT"] = "Strategi Melawan",
  ["str_guide_circle_13-14_Rb"] = "Prioritaskan menyerang bunga Diavola terlebih dahulu untuk melumpuhkannya agar dapat memberikan kerusakan dengan aman. Ingatlah untuk menjaga Dawn Sprite yang dipanggilnya.",
  ["str_guide_circle_13-7-1_Lt"] = "Sebuah Eclipsite lahir dalam kondisi ekstrim di akhir zaman. Ia memiliki sosok yang terdistorsi dan telah lama kehilangan kemampuan untuk berpikir secara cerdas. Yang tersisa hanyalah keinginan untuk terus bergerak maju dan melahap segala sesuatu di jalannya.",
  ["str_guide_circle_13-7-1_LtT"] = "Jormungand",
  ["str_guide_circle_13-7-1_Rt"] = "Kepala Jormungand adalah inti dari serangannya. Ini memberikan banyak kerusakan pada musuh di dekat kepalanya. Jormungand mati ketika kepalanya memiliki sisa 0 HP.",
  ["str_guide_circle_13-7-1_RtT"] = "Ciri-ciri Kepala Jormungand",
  ["str_guide_circle_13-7-1_Rb"] = "Pemain harus ingat untuk memberikan damage ke kepala Jormungand dari jarak jauh. Jormungand akan langsung mati jika kepalanya terhalang oleh rintangan di semua sisi.",
  ["str_guide_circle_13-7-1_RbT"] = "Strategi Melawan",
  ["str_guide_circle_13-7-2_Lt"] = "Tubuh Jormungand mereplikasi dirinya sendiri dari waktu ke waktu dan tumbuh lebih panjang setiap putaran. Tubuhnya kebal terhadap semua kerusakan.",
  ["str_guide_circle_13-7-2_LtT"] = "Ciri-ciri Tubuh Jormungand",
  ["str_guide_circle_13-7-3_Lt"] = "Ekor Jormungand adalah titik lemahnya. Semua kerusakan yang diberikan pada ekor akan ditransfer ke kepala, dan Anda akan memberikan lebih banyak kerusakan.",
  ["str_guide_circle_13-7-3_LtT"] = "Ciri-ciri Ekor Jormungand",
  ["str_guide_circle_14-9-1_LtT"] = "Roh Lentera",
  ["str_guide_circle_14-9-1_Lt"] = "Eclipsite yang dimodifikasi oleh Asmodeus. Keinginannya dikendalikan oleh Asmodeus, jadi dia mematuhi setiap perintahnya.",
  ["str_guide_circle_14-9-1_RtT"] = "Ciri-Ciri Monster I",
  ["str_guide_circle_14-9-1_Rt"] = "Jika Roh Lentera dapat Teleportasi melalui Aurorian saat menyerang, itu menciptakan rantai yang menyebabkan kerusakan yang diterima dan pemulihan HP dibagi antara pihak terkait.",
  ["str_guide_circle_14-9-1_RbT"] = "Teleportasi",
  ["str_guide_circle_14-9-1_Rb"] = "Lantern Spirit dapat berteleportasi jika dapat melewati petak tempat Aurorian berada dan berpindah ke petak di sisi lain.",
  ["str_guide_circle_14-9-2_LtT"] = "Rantai",
  ["str_guide_circle_14-9-2_Lt"] = "Ketika salah satu pihak yang terhubung oleh rantai menerima kerusakan atau memulihkan HP, pihak lain akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama.",
  ["str_guide_circle_14-9-2_RtT"] = "Strategi Melawan",
  ["str_guide_circle_14-9-2_Rt"] = "Jaga jarak tertentu dari Roh Lentera untuk memutus rantai.",
  ["str_guide_circle_14-9-2_RbT"] = "Kalahkan atau tarik mereka!",
  ["str_guide_circle_14-9-2_Rb"] = "Mengalahkan atau menarik Roh Lentera ke arah Anda juga merupakan cara untuk melepaskan diri dari rantai yang menghubungkan Anda.",
  ["str_guide_circle_14-14-1_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-1_Lt"] = "Wraith yang kuat memiliki kemampuan yang mengerikan untuk melihat semua keinginan lawannya dan senang memanipulasi mereka.",
  ["str_guide_circle_14-14-1_RtT"] = "Ciri-ciri Gerhana",
  ["str_guide_circle_14-14-1_Rt"] = "Asmodeus terbagi menjadi dua saat memasuki lapangan. Satu klon kebal terhadap kemampuan, dan yang lainnya kebal terhadap serangan normal. Mereka dihubungkan oleh Rantai Keinginan.",
  ["str_guide_circle_14-14-1_RbT"] = "Rantai Keinginan",
  ["str_guide_circle_14-14-1_Rb"] = "Ketika salah satu Asmodeus yang terhubung oleh Rantai Keinginan mengalami damage atau pemulihan HP, Asmodeus lainnya akan mengalami efek yang sama. Setelah Asmodeus melakukan tindakan, Wilayah Gelap akan dihasilkan di bawah Rantai Keinginan.",
  ["str_guide_circle_14-14-2_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-2_Lt"] = "Asmodeus ini kebal terhadap kerusakan serangan normal dan memiliki serangan jarak jauh yang kuat.",
  ["str_guide_circle_14-14-3_RtT"] = "Asmodeus",
  ["str_guide_circle_14-14-3_Rt"] = "Asmodeus ini kebal terhadap kerusakan skill dan menghubungkan dirinya dengan Aurorian yang dia serang dengan Chain of Nightmares miliknya.",
  ["str_guide_circle_14-14-3_RbT"] = "Rantai Mimpi Buruk",
  ["str_guide_circle_14-14-3_Rb"] = "Aurorian yang terhubung dengan Chain of Nightmares akan menerima damage untuk setiap petak yang mereka lalui. Meninggalkan jangkauan efektif Chain of Nightmares akan menghancurkannya.",
  ["str_guide_circle_14-7_LtT"] = "Cerritus",
  ["str_guide_circle_14-7_Lt"] = "Eclipsite baru yang ditemui selama eksplorasi tampaknya merupakan varian dari Eclipsite yang kuat, kecuali itu lebih gila dan jauh lebih merusak.",
  ["str_guide_circle_14-7_RtT"] = "Monster Trait",
  ["str_guide_circle_14-7_Rt"] = "Cerritus menyerang Aurorian dengan menabrak mereka dan memiliki kemampuan yang kuat untuk memanggil Kerikil dan mengubah medan. Cerritus tumbuh lebih kuat saat pertempuran berlangsung. Serangan yang tidak membunuh Cerritus hanya membuatnya lebih kuat! Setiap beberapa putaran, Cerritus mengaum dengan marah dan memasuki keadaan gila.",
  ["str_guide_circle_14-7_RbT"] = "Strategi Melawan",
  ["str_guide_circle_14-7_Rb"] = "Perhatikan posisi relatif Anda dari musuh. Gunakan keterampilan pada waktu yang tepat untuk mengakhiri pertempuran dengan cepat.",
  str_guide_circle_N24_petTry_LtT = "Bola Penyembuh",
  str_guide_circle_N24_petTry_Lt = "Benda yang dipanggil Axelia. Dia menyembuhkan dirinya sendiri saat dia menyerap ini dengan Skill Aktifnya atau saat tim melewatinya. Berubah setelah ada selama 2 putaran, memberikan efek penyembuhan tambahan.",
  str_guide_circle_N24_petTry_Lt_1 = "Benda yang dipanggil Axelia. Dia menyembuhkan dirinya sendiri saat dia menyerap ini dengan Skill Aktifnya atau saat tim melewatinya.",
  ["str_guide_circle_N25_1-4_LtT"] = "Venomex",
  ["str_guide_circle_N25_1-4_Lt"] = "Dikatakan sebagai kerabat jauh dari spesies Eclipsite yang mampu meledakkan diri, kecuali varietas ini dapat meluncurkan bola lendir berbisa, memberikan kerusakan signifikan pada organisme hidup.",
  ["str_guide_circle_N25_1-4_LbT"] = "Monster Trait",
  ["str_guide_circle_N25_1-4_Lb"] = "Menyemprotkan racun dalam garis lurus atau di lokasi Aurorian, menimbulkan Racun pada semua musuh dan sekutu dalam jangkauan racun.",
  ["str_guide_circle_N25_1-4_RtT"] = "Strategy",
  ["str_guide_circle_N25_1-4_Rt"] = "Mungkin Anda bisa menggunakan racunnya untuk membuat musuh lain menderita.",
  ["str_guide_circle_N25_1-16_RtT"] = "Dreamwalker",
  ["str_guide_circle_N25_1-16_Rt"] = "Konon, dia adalah \"saudara\" Phantom di Eternal Night. Dia mampu melancarkan taktik yang berbeda berdasarkan waktu saat itu dan sangat sulit untuk dihadapi.",
  ["str_guide_circle_N25_1-16_LtT"] = "Monster Trait",
  ["str_guide_circle_N25_1-16_Lt"] = "Memiliki kemampuan menyerang Aurorian dari jarak jauh dan dapat melancarkan serangan layar penuh. Bisa memanggil hantu yang mengelilingi Aurorian tapi tidak bisa menyerang.",
  ["str_guide_circle_N25_1-16_LbT"] = "Strategy",
  ["str_guide_circle_N25_1-16_Lb"] = "Andalkan gerakan gesit untuk menghindari dikelilingi oleh Phantasm.",
  ["str_guide_circle_N25_2-4_LtT"] = "Menipu",
  ["str_guide_circle_N25_2-4_Lt"] = "Memiliki kemampuan luar biasa untuk berbaur dengan lingkungannya. Terkadang, bahkan terlihat seperti jebakan biasa. Namun, begitu ia mengungkapkan dirinya, ia meledak dalam amukan yang mematikan.",
  ["str_guide_circle_N25_2-4_LbT"] = "Monster Trait",
  ["str_guide_circle_N25_2-4_Lb"] = "Biasanya bersembunyi di Crud. Saat hitungan mundur selesai, ia muncul dan menyerang Aurorian.",
  ["str_guide_circle_N25_2-4_RtT"] = "Strategi Melawan",
  ["str_guide_circle_N25_2-4_Rt"] = "Menyetel ulang petak tempat Crud berada akan menghapus Crud dan membuat Cozen muncul.",
  ["str_guide_circle_N26_1-12_RtT"] = "Yoh",
  ["str_guide_circle_N26_1-12_Rt"] = "Pernah menjadi pemimpin ikan ular, dia diperbudak oleh Aurorian untuk dijadikan alat navigasi. Kebencian yang meningkat selama bertahun-tahun telah mengubahnya menjadi musuh yang kuat.",
  ["str_guide_circle_N26_1-12_LtT"] = "Monster Trait",
  ["str_guide_circle_N26_1-12_Lt"] = "Memiliki kemampuan sihir yang kuat dan dapat mengontrol proyektil untuk memberikan kerusakan pada musuh.",
  ["str_guide_circle_N26_1-12_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N26_1-12_Lb"] = "Bersihkan \"Word\" dan replika di lapangan sesegera mungkin untuk menghindari kerusakan parah.",
  ["str_guide_circle_N27_1-1_RtT"] = "Asisten Aphonic",
  ["str_guide_circle_N27_1-1_Rt"] = "Kemungkinan jenis \"mentor\" Eclipsite tertentu, mengingat bagaimana mereka berdua menyembuhkan Eclipsites lainnya. Perbedaannya adalah bahwa Eclipsite ini lebih mungkin untuk tetap dekat dengan sekutunya yang lebih besar untuk memanfaatkan efek khusus keahliannya.",
  ["str_guide_circle_N27_1-1_LtT"] = "Monster Trait",
  ["str_guide_circle_N27_1-1_Lt"] = "Dapat memulihkan HP Eclipsites lainnya. Semakin banyak petak yang ditempati Eclipsite lain dalam jangkauan skill Aphonic Assistant, semakin kuat efek penyembuhannya.",
  ["str_guide_circle_N27_1-1_LbT"] = "Strategi Melawan",
  ["str_guide_circle_N27_1-1_Lb"] = "Prioritaskan berurusan dengan Aphonic Assistant, dan cegah Aphonic Assistant menyembuhkan Eclipsites lainnya!",
  ["str_guide_circle_N27_1-12_LtT"] = "Cacing Pasir Merah Muda",
  ["str_guide_circle_N27_1-12_Lt"] = "Cacing pasir langka yang berasal dari Gurun Rediesel. Itu ditutupi sisik merah muda karena mutasi yang unik, membuatnya lebih kuat dan lebih ganas daripada cacing pasir lainnya.",
  ["str_guide_circle_N27_1-12_RtT"] = "Monster Trait",
  ["str_guide_circle_N27_1-12_Rt"] = "Mengebor ke tanah untuk menemukan lokasi targetnya, lalu meledak ke tempat terbuka. Meludahkan pasir hitam untuk menyerang target di depannya.",
  ["str_guide_circle_N27_1-12_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N27_1-12_Rb"] = "Menghindari serangan Pink Sandworm bisa jadi rumit! Perhatikan status Anda sendiri setiap saat dan akhiri pertempuran secepat mungkin!",
  ["str_guide_circle_N27_2-4-1_RbT"] = "Derek Kertas",
  ["str_guide_circle_N27_2-4-1_Rb"] = "Derek Kertas dapat ditempatkan pada ubin Abyssal dan mengubah ubin di bawahnya menjadi ubin berwarna. Bangau Kertas akan menghilang setelah tim melewatinya.",
  ["str_guide_circle_N27_2-4-2_RbT"] = "Aurorian Assistance",
  ["str_guide_circle_N27_2-4-2_Rb"] = "Pasolo dapat menempatkan Bangau Kertas di atas ubin untuk membantu timnya mengatasi situasi sulit. Ingatlah untuk menggunakan bantuan keterampilan Pasolo setiap putaran!",
  str_guide_circle_N27_2_1_RtT = "Cadangan Lumo",
  str_guide_circle_N27_2_1_Rt = "Tim cadangan dari Lumopolis telah bergabung dalam pertempuran. Sekutu Piker akan bertindak setelah Eclipsites. Konstruktor akan memanggil Piker saat pemain menggunakan Skill Aktif 3 kali berturut-turut.",
  str_guide_circle_N27_2_1_RbT = "Peringatan!",
  str_guide_circle_N27_2_1_Rb = "Lindungi Konstruktor sekutu terlebih dahulu! Setelah Pembuatnya dikalahkan, Lumo Piker sekutu harus mundur. DEF semua Aurorian di papan juga akan sangat melemah.",
  str_guide_circle_N27_2_2_RbT = "Sasaran Serang",
  str_guide_circle_N27_2_2_Rb = "Eclipsites akan menyerang Lumo Backup kita terlebih dahulu. Setelah semua tim Cadangan Lumo di papan dikalahkan, Eclipsites akan mengubah target mereka dan menyerang pemain.",
  str_guide_circle_N27_2_2_LbT = "Pertarungan Fraksi",
  str_guide_circle_N27_2_2_Lb = "Mata Jahat musuh akan terus memanggil Eclipsites ke medan perang. Pemain harus melindungi Konstruktor sekutu dan mengalahkan Brood musuh.",
  str_guide_circle_N28_3_4_RtT = "Lubang cacing",
  ["str_guide_circle_N28_3-4_Rt"] = "Eclipsites dapat melarikan diri ke lokasi lain melalui lubang cacing.",
  ["str_guide_circle_N28_3-4_RbT"] = "Strategi Melawan",
  ["str_guide_circle_N28_3-4_Rb"] = "Mencegah Eclipsite melarikan diri dengan mengalahkan mereka atau menggunakan kemampuan yang memaksa mereka untuk bergerak.",
  str_guide_circle_N28_1_12_LtT = "Empat Ksatria",
  str_guide_circle_N28_1_12_Lt = "Meski terlihat seperti anggota juri biasa, tutup kepala plester di kepala mereka membuat mereka terlihat sangat mencurigakan. Ternyata Eclipsites bersembunyi di bawah mereka! Hal yang membingungkan adalah mereka sepertinya mengikuti instruksi seseorang...",
  str_guide_circle_N28_1_12_LbT = "Monster Trait",
  str_guide_circle_N28_1_12_Lb = "Setiap kali salah satu dari Empat Ksatria diserang atau memulihkan HP, ksatria lainnya akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama.",
  str_guide_circle_N28_1_12_RbT = "Strategi Melawan",
  str_guide_circle_N28_1_12_Rb = "Hati-hati amati posisi Empat Ksatria dan bertindak dengan hati-hati!",
  str_guide_circle_N29_zhanqi_1_LtT = "Lubang cacing",
  str_guide_circle_N29_zhanqi_1_Lt = "Membantu Eclipsites bergerak lebih cepat melintasi medan perang.",
  str_guide_circle_N29_zhanqi_1_LbT = "Strategi Melawan",
  str_guide_circle_N29_zhanqi_1_Lb = "Menghindari konflik dengan Aurorian dan melewati perangkat teleportasi sesegera mungkin tampaknya menjadi pilihan yang lebih masuk akal.",
  str_guide_circle_N29_1_8_LbT = "Setan Hati",
  str_guide_circle_N29_1_8_Lb = "Kenangan masa lalu membanjiri hatinya, menciptakan Demon Hound yang menakutkan saat kebencian menguasai dirinya.",
  str_guide_circle_N29_1_8_RbT = "Monster Trait",
  str_guide_circle_N29_1_8_Rb = "Demon Hati mengkonsumsi sebagian dari HP-nya untuk menyerang dan memulihkan sebagian dari HP-nya yang hilang jika ada Aurorian yang terkena. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang!",
  str_guide_circle_N29_1_14_LbT = "Setan Hati",
  str_guide_circle_N29_1_14_Lb = "Kenangan masa lalu membanjiri hatinya, menciptakan Demon Hound yang menakutkan saat kebencian menguasai dirinya.",
  str_guide_circle_N29_1_14_RbT = "Monster Trait",
  str_guide_circle_N29_1_14_Rb = "Demon Hati mengkonsumsi sebagian dari HP-nya untuk menyerang dan memulihkan sebagian dari HP-nya yang hilang jika ada Aurorian yang terkena. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang!",
  str_guide_circle_N29_1_14_LbT_2 = "Awas!",
  str_guide_circle_N29_1_14_Lb_2 = "Ketika Demon Hati berada di ambang kematian, dia dapat mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh. Dia juga akan mendapatkan skill yang kuat dan meningkatkan efek skillnya!",
  str_guide_circle_N29_ex3_1_LbT = "Setan Hati",
  str_guide_circle_N29_ex3_1_Lb = "Kenangan masa lalu membanjiri hatinya, menciptakan Demon Hound yang menakutkan saat kebencian menguasai dirinya.",
  str_guide_circle_N29_ex3_1_RbT = "Monster Trait",
  str_guide_circle_N29_ex3_1_Rb = "Demon Hati mengkonsumsi sebagian dari HP-nya untuk menyerang dan memulihkan sebagian dari HP-nya yang hilang jika ada Aurorian yang terkena. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang!",
  str_guide_circle_N29_ex3_1_LbT_2 = "Awas!",
  str_guide_circle_N29_ex3_1_Lb_2 = "Ketika Demon Hati berada di ambang kematian, dia dapat mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh. Dia juga akan mendapatkan skill yang kuat dan meningkatkan efek skillnya!",
  str_guide_circle_N29_ex3_1_RbT_2 = "Peringatan!",
  str_guide_circle_N29_ex3_1_Rb_2 = "Demon Hati melawan Skill Aktif jika Aurorian melemparkannya ke arahnya.",
  str_guide_warn_11900702 = "Ini adalah tingkat penyempurnaan dari peralatan saat ini. Setiap peralatan dapat disempurnakan 3 kali.",
  str_guide_warn_11900703 = "Efek penyempurnaan peralatan ditampilkan di sini. Selain meningkatkan atribut dasar, refinement juga dapat meningkatkan skill Aurorian.",
  str_guide_warn_11900704 = "Selain memenuhi persyaratan pembukaan kunci dasar untuk penyempurnaan, Aurorian juga perlu mengonsumsi bahan yang sesuai.",
  str_guide_warn_11900802 = "Ini adalah tingkat penyempurnaan dari peralatan saat ini. Setiap peralatan dapat disempurnakan 3 kali.",
  str_guide_warn_11900803 = "Efek penyempurnaan peralatan ditampilkan di sini. Selain meningkatkan atribut dasar, refinement juga dapat meningkatkan skill Aurorian.",
  str_guide_warn_11900804 = "Selain memenuhi persyaratan pembukaan kunci dasar untuk penyempurnaan, Aurorian juga perlu mengonsumsi bahan yang sesuai.",
  str_guide_warn_11900805 = "Paradigma dapat diperoleh melalui penghargaan Aktivitas mingguan, di antara metode lainnya. Ketuk ikon untuk melihat daftar detail sumber Paradigma.",
  ["str_guide_circle_N30_15-2_RtT"] = "Prajurit Illumina",
  ["str_guide_circle_N30_15-2_Rt"] = "Prajurit tempur biasa di Tentara Illumina, dikenal karena keterampilan mereka dengan senapan dan pisau tempur, serta keuletan, etos kerja, proaktif dalam pertempuran, dan semangat juang yang tak kenal takut.",
  ["str_guide_circle_N30_15-2_LbT"] = "Monster Trait",
  ["str_guide_circle_N30_15-2_Lb"] = "Menggunakan lebih banyak serangan jarak jauh. Ketika pertempuran sengit, mendekati musuh dan terlibat dalam pertempuran jarak dekat untuk menghabisi mereka secepat mungkin.",
  ["str_guide_circle_N30_15-2_RbT"] = "Awas!",
  ["str_guide_circle_N30_15-2_Rb"] = "Ketika HP lebih rendah dari 50%, semua serangan senjata akan menjadi serangan jarak dekat dengan pisau tempur. Pada saat yang sama, semua Bruise yang terkumpul akan berubah menjadi HP yang dipulihkan dan meningkatkan ATK dan DEF.",
  ["str_guide_circle_N30_15-9_Lt"] = "Robot tempur yang dikembangkan oleh Illumina. Itu telah bekerja sangat baik dalam pengujian internal tetapi belum diuji dalam pertempuran yang sebenarnya.",
  ["str_guide_circle_N30_15-9_LtT"] = "Pembor",
  ["str_guide_circle_N30_15-9_Lb"] = "Pengebor memiliki 2 status. Itu bergerak di sekitar lapangan dalam keadaan normal dan menggali sejumlah Bidang Energi dan Bidang Pendukung setiap putaran. Ketika ada sejumlah Medan Energi di lapangan, itu menyerap dan merakit Anjungan Pengebor.",
  ["str_guide_circle_N30_15-9_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_N30_15-9_Rb"] = "Ketika ada lebih sedikit Bidang Pendukung di lapangan, Pengebor menggali lebih banyak Bidang Pendukung.",
  ["str_guide_circle_N30_15-9_RbT"] = "Catatan",
  ["str_guide_circle_N30_15-9-2_Lt"] = "Medan Energi adalah ubin berenergi penuh yang dapat digunakan untuk merakit Anjungan Pengebor. Itu menghentikan bagian unit di tanah saat itu ada.",
  ["str_guide_circle_N30_15-9-2_LtT"] = "Bidang Energi",
  ["str_guide_circle_N30_15-9-2_Rb"] = "Jika ada 6 Medan Energi di medan perang saat Pengebor mengambil tindakan, Pengebor memicu keahlian khusus, membangun Platform Pengebor.",
  ["str_guide_circle_N30_15-9-2_RbT"] = "Bagian yang diperlukan untuk perakitan.",
  ["str_guide_circle_N30_16-14_Lt"] = "Sebagai salah satu Wraith terkuat, dia menyerang dengan seluruh kekuatannya saat statusnya terancam.",
  ["str_guide_circle_N30_16-14_LtT"] = "Figerald",
  ["str_guide_circle_N30_16-14_Lb"] = "Ubin runtuh setelah Aurorian bergerak melintasinya. Ketika tidak ada cukup ubin di medan perang, Figerald melepaskan kekuatannya untuk membentuk ulang ruang dan memberikan kerusakan.",
  ["str_guide_circle_N30_16-14_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_N30_16-14_Rt"] = "Rencanakan rute Anda dengan baik untuk meminimalkan berapa kali Anda menerima kerusakan saat Figerald membentuk ulang ruang.",
  ["str_guide_circle_N30_16-14_RtT"] = "Strategi Melawan",
  str_guide_circle_N30_tower10_LtT = "Pemburu Mekanik",
  str_guide_circle_N30_tower10_LbT = "Karakteristik Musuh",
  str_guide_circle_N30_tower10_RbT = "Peringatan!",
  str_guide_circle_N30_tower10_Lt = "Seorang wali kuno diciptakan untuk satu-satunya tujuan melindungi rahasia tanah ini. Serangannya sulit untuk dihindari, dan ia juga memiliki pemulihan diri yang luar biasa agar tetap berfungsi selama berabad-abad. Tidak ada yang mau menghadapinya sendirian.",
  str_guide_circle_N30_tower10_Lb = "Membuat zona yang dijaga dalam 2 kelompok sekitarnya setiap putaran. Aurorian di dalam zona yang dijaga akan menerima kerusakan tambahan setiap kali mereka menyerang atau bergerak. Jika Pemburu Mekanik tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh.",
  str_guide_circle_N30_tower10_Rb = "Saat Pemburu Mekanik memasuki kondisi tak terkalahkan, ia melepaskan serangan yang sangat berbahaya yang mengurangi semua musuh di zona yang dijaga menjadi 1 HP di ronde berikutnya.",
  str_guide_circle_N30_tower10_3_LtT = "Bennuguardian",
  str_guide_circle_N30_tower10_3_Lt = "Seorang wali kuno yang berada di kedalaman Wilayah Rahasia, terbangun karena seringnya gangguan dari penyusup. Bahkan Eclipsites takut dengan kemampuannya yang kuat. Berkeliaran di sekitar medan perang tanpa tujuan.",
  str_guide_circle_N30_tower10_3_LbT = "Karakteristik Musuh",
  str_guide_circle_N30_tower10_3_Lb = "Memiliki kekuatan besar. Mengumpulkan Fury saat diserang. Ketika Fury mencapai level tertentu, memasuki kondisi Marah, mengurangi kerusakan yang diterima dan memberikan keterampilan tambahan yang kuat. Jika Bennuguardian tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh.",
  str_guide_circle_N30_tower10_3_RbT = "Peringatan!",
  str_guide_circle_N30_tower10_3_Rb = "Pantau Kemarahan Bennuguardian setiap saat dan bertindak hati-hati!",
  ["str_guide_circle_15-14_LtT"] = "Uji Negara Helios",
  ["str_guide_circle_15-14_Lt"] = "Setelah hidup sendirian selama lebih dari satu dekade di Dark Zone, prajurit Illumina ini telah melupakan segalanya kecuali pertempuran. Hal yang menakutkan adalah dia menjadi lebih kuat dalam pertempuran setelah dimodifikasi oleh seseorang ...",
  ["str_guide_circle_15-14_RtT"] = "Karakteristik Musuh",
  ["str_guide_circle_15-14_Rt"] = "Entitas yang memiliki kemampuan tempur yang kuat dan mengumpulkan Memar saat menerima kerusakan. Saat serangannya meleset dari targetnya, Tanda Teror dilepaskan di lapangan. Keterampilan Helios menjadi lebih kuat dengan setiap Tanda Teror di lapangan.",
  ["str_guide_circle_15-14_RbT"] = "Strategi Melawan",
  ["str_guide_circle_15-14_Rb"] = "Catat di mana tandanya untuk menghindari serangan Helios!",
  str_guide_circle_621_RtT = "Ubin Prisma Berbentuk Silang",
  str_guide_circle_621_Rt = "Saat dihubungkan dengan ubin lain, 4 ubin di sekelilingnya dalam bentuk silang diubah menjadi warna yang sama.",
  ["str_guide_circle_N30_16-9_Lt"] = "Eclipsite khusus ini menyerupai laba-laba dan telah mempelajari perilaku kelompok laba-laba selama jalur evolusinya. Itu bersembunyi di kegelapan di mana sinar matahari tidak bisa mencapai.",
  ["str_guide_circle_N30_16-9_LtT"] = "Ratu laba-laba",
  ["str_guide_circle_N30_16-9_Lb"] = "Memiliki kemampuan reproduksi yang kuat, ia menjalin jaring laba-laba ke dalam lingkungan berburu.",
  ["str_guide_circle_N30_16-9_LbT"] = "Monster Trait",
  ["str_guide_circle_N30_16-9_Rt"] = "Fokuskan perhatian Anda untuk membersihkan jaring, dan bersihkan Telur Laba-laba dan Tukik Laba-laba yang dipanggil Ratu Laba-laba secepat mungkin.",
  ["str_guide_circle_N30_16-9_RtT"] = "Strategi Melawan",
  ["str_guide_circle_N30_16-3_Lt"] = "Seorang anggota Illumina yang luar biasa dan ahli pertarungan jarak dekat yang bersahaja dengan kemampuan untuk mendeteksi dan bereaksi terhadap gerakan musuh selama pertempuran sengit, memungkinkan serangan balik yang efektif.",
  ["str_guide_circle_N30_16-3_LtT"] = "Prajurit Elit Illumina",
  ["str_guide_circle_N30_16-3_Lb"] = "Setiap kali musuh menggunakan Skill Aktif, langsung memajukan 1 ubin ke arah musuh dan menyerang.",
  ["str_guide_circle_N30_16-3_LbT"] = "Kemampuan Kontra",
  ["str_guide_circle_N30_16-3_Rt"] = "Mengumpulkan Memar saat menerima kerusakan. Jika pemain tidak memberikan damage pada unit ini selama ronde ini, segera sembuhkan semua Memar untuk memulihkan HP.",
  ["str_guide_circle_N30_16-3_RtT"] = "Peningkatan Ulet",
  str_guide_warn_12000101 = "Acara Descent Illumination sekarang sedang berlangsung! Selama periode event, Illumina Supply Center akan dibuka untuk semua Navigator!",
  str_guide_warn_12000102 = "Pas Persediaan yang diperoleh dengan membelanjakan Prism dapat ditukar dengan berbagai hadiah di Pusat Persediaan Illumina.",
  str_guide_warn_12000103 = "Masuki simulator latihan militer Pertempuran Tim baru Gronru untuk terlibat dalam pelatihan komprehensif dengan Aurorian Anda!",
  str_guide_warn_12000104 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_12000105 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_12000106 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_12100101 = "Perjalanan ke Masa Lalu kini telah dimulai! Kami akan mengunjungi kembali masa lalu dengan Mia pada Hari Keluarga dan mengungkap kebenaran di balik apa yang terjadi!",
  str_guide_warn_12100102 = "Di Jurang Tanpa Dasar, kita akan menghadapi serangkaian tantangan yang sulit.",
  str_guide_warn_12100103 = "Tetesan Kristal yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menukarkan berbagai hadiah dari Ruang Ramalan.",
  str_guide_warn_12100104 = "Ingatlah untuk masuk ke dalam game setiap hari untuk mendapatkan hadiah On Memories of Old.",
  str_guide_warn_12100105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_12100106 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  ["str_guide_circle_N31_1-14_Lt"] = "Mime Kartima mengacungkan tamengnya, mengurangi damage dari serangan frontal. Kehilangan efek saat tertegun, ketakutan, lumpuh, atau terkena efek kontrol lainnya.",
  ["str_guide_circle_N31_1-14_LtT"] = "Kartima: Penjaga perisai",
  ["str_guide_circle_N31_1-14_Lb"] = "Mime Kartima kebal untuk mengontrol efek selama 2 putaran setelah bergabung dalam pertempuran.",
  ["str_guide_circle_N31_1-14_LbT"] = "Kartima: Pantang menyerah",
  ["str_guide_circle_N31_1-14_Rt"] = "Mime Kartima menggunakan palu rantai untuk menyerang area di depan sebelah kanannya atau menggunakan perisai untuk memukul mundur target di depan sebelah kiri",
  ["str_guide_circle_N31_1-14_RtT"] = "Teknik Pertempuran",
  ["str_guide_circle_N31_1-16_Lt"] = "Dia memiliki kontrol yang sangat besar atas lingkungannya dan sebagian tahan terhadap serangan dan keterampilan normal karena efek dari Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LtT"] = "Joshua: Jiwa yang Tercemar",
  ["str_guide_circle_N31_1-16_Lb"] = "Pilih strategi aksi yang berbeda, seperti apakah akan menggunakan serangan normal atau skill melawan Joshua: Tainted Soul di babak saat ini berdasarkan efek Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LbT"] = "Teknik Pertempuran",
  str_guide_popstar_fail_tip = "Strategi Eliminasi",
  str_guide_popstar_fail_desc = "Gunakan keterampilan Aurorian untuk menghilangkan ubin sebanyak mungkin di setiap langkah. Saat melepas ubin, pikirkan dengan hati-hati tentang kondisi ubin selama langkah selanjutnya akan membuat segalanya jauh lebih mudah bagi Anda.",
  str_guide_circle_N31_star1_Rt = "Dapat dilepas bersama dengan ubin. Jika tidak dihapus, ubin berubah menjadi rusak setelah hitungan mundur berakhir.",
  str_guide_circle_N31_star1_RtT = "Ubin Rune",
  str_guide_circle_N31_star2_Rt = "Saat menghapus ubin yang ditingkatkan, ubin ini diperlakukan sebagai ubin tambahan yang dihapus.",
  str_guide_circle_N31_star2_RtT = "Enhanced Tile",
  str_guide_circle_N31_star3_Rt = "Ubin yang terkunci tidak dapat diubah warnanya. Setelah menghapus ubin yang terkunci, mereka diubah menjadi ubin normal.",
  str_guide_circle_N31_star3_RtT = "Tile Terkunci",
  str_guide_warn_6012102 = "Ketuk di sini untuk melihat informasi rank.",
  str_guide_warn_6012104 = "Ketuk di sini untuk melihat Peringkat.",
  str_guide_warn_6012106 = "Ketuk di sini untuk melanjutkan menonton.",
  str_guide_warn_6012107 = "Kamu bisa mendapatkan Forgotten Utterances dan Forgotten Whispers dengan menyelesaikan Hunting Bounty.",
  str_guide_warn_6012108 = "Para navigator dapat menukar Ujaran yang Terlupakan dan Bisikan yang Terlupakan di Exiled Harborage dengan Solamber, Aurorian, dan Star Flare.",
  str_guide_warn_6012202 = "Kami dapat mengatur beberapa tim untuk menantang bos. Kerusakan total semua tim kami akan dicatat sebagai hasil akhir.",
  str_guide_warn_6012203 = "Peringkat atau lambang tidak akan tersedia jika Anda belum memulai tantangan.",
  str_guide_warn_6012204 = "Ketuk di sini untuk melihat informasi rank.",
  str_guide_warn_6012206 = "Ketuk di sini untuk melihat Peringkat Anda Saat Ini.",
  str_guide_warn_6012208 = "Ketuk di sini untuk melanjutkan menonton.",
  str_guide_warn_6012209 = "Kamu bisa mendapatkan Forgotten Utterances dan Forgotten Whispers dengan menyelesaikan Hunting Bounty.",
  str_guide_warn_6012210 = "Para navigator dapat menukar Ujaran yang Terlupakan dan Bisikan yang Terlupakan di Exiled Harborage dengan Solamber, Aurorian, dan Star Flare.",
  str_guide_warn_12200201 = "Hah? dimana saya? Apakah itu... Crystal of Eternal Memory lainnya?",
  str_guide_warn_12200202 = "Apakah kita gagal keluar pada akhirnya...? Tidak apa-apa! Ucapkan mantra perjalanan waktu dengan lantang dan ketuk di sini!",
  str_guide_warn_12200301 = "Ssst... Seseorang sepertinya sedang berbicara di dekatnya. Ahem, aku tidak menguping! Ini disebut... pengumpulan informasi!",
  str_guide_warn_12200401 = "Melihat? Saya tahu saya benar. Kami mendapatkan informasi yang luar biasa! Apa? Anda tidak dapat mengingat semuanya? Kemudian taruh informasi yang kami kumpulkan di sini!",
  str_guide_warn_12200402 = "Lihat, semua informasi ada di sini, sekarang Anda tidak perlu khawatir lupa! Perhatikan segala sesuatu di sekitar Anda dan isi semua ruang ini.",
  str_guide_warn_12200101 = "Edge of Collapse telah dimulai! Dalam The Divergence, kita akan menyelidiki misteri Crystal of Eternal Memory!",
  str_guide_warn_12200102 = "Kita akan menghadapi serangkaian tantangan sulit di dunia Shattered Illusion.",
  str_guide_warn_12200103 = "Crystal Teardrops yang didapatkan dengan menyelesaikan stage event dan membelanjakan Prism dapat ditukarkan dengan berbagai hadiah di Hall of Remembrance.",
  str_guide_warn_12200104 = "Ingatlah untuk masuk ke dalam game setiap hari untuk mendapatkan hadiah Musing Sedih.",
  str_guide_warn_12200105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_12200106 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_circle_N33_15_Lt = "Sebuah kupu-kupu yang sangat langka, dikabarkan hanya muncul di dekat Lembah Denuo. Sifatnya penyendiri, dengan indera yang sangat tajam. Kekuatan tempur Dewi Denuo dewasa tidak boleh diremehkan.",
  str_guide_circle_N33_15_LtT = "Dewi Denuo",
  str_guide_circle_N33_15_Lb = "Mereka mengkatalis pertumbuhan tanaman melalui penyerbukan, melindungi diri mereka sendiri sambil menimbulkan kerusakan besar pada musuh.",
  str_guide_circle_N33_15_LbT = "Karakteristik Musuh",
  str_guide_circle_N33_15_Rt = "Pilih jalur Anda dengan bijak untuk mencegah Dewi Denuo menyerbuki Gulma Sihir Sadesian, membuatnya lebih agresif.",
  str_guide_circle_N33_15_RtT = "Strategi Melawan",
  str_guide_circle_chapter18_14_Rb = "Lakukan serangan intensif untuk melumpuhkan Engine VII yang Terkorupsi, tunda serangannya pada gerbang Benteng Illumina.",
  str_guide_circle_chapter18_14_RbT = "Strategi Melawan",
  str_guide_circle_chapter18_14_Rt = "Awalnya mecha tempur raksasa yang dibuat oleh Illumina, namun berubah menjadi ancaman yang sangat ditakuti setelah pilotnya kehilangan akal karena terkontaminasi oleh lumpur.",
  str_guide_circle_chapter18_14_RtT = "Corrupted Engine VII",
  str_guide_warn_80010102 = "Hanya Anda yang bisa memasuki mimpi Hawa ...",
  str_guide_warn_80010103 = "Selesaikan misi yang dirinci dalam Fragmen Memori untuk mendapatkan Lumamber, dan temukan alur cerita yang tersembunyi Eve.",
  str_guide_warn_80010104 = "Metamorpha dan Sediment Shard yang diperoleh di dalam Mimpi dapat ditukarkan dengan berbagai hadiah di sini, termasuk pakaian Eve.",
  str_guide_warn_80010105 = "Pernak-pernik kecil yang dikumpulkan dalam Mimpi semuanya disimpan dengan hati-hati di sini Eve.",
  str_guide_warn_80010106 = "Selesaikan misi di Dream untuk mendapatkan Stand By Me Set.",
  str_guide_warn_80010107 = "Ketuk di sini untuk melihat detailnya.",
  str_guide_warn_80010202 = "Ini... sepertinya cangkir yang diberikan kepadaku oleh seseorang yang spesial.",
  str_guide_warn_80010203 = "Saya ingat, cawan ini dapat memberi saya kekuatan khusus!",
  str_guide_warn_80010204 = "Hah? Cangkirnya kosong... Aku perlu mengumpulkan Ripples of Joy untuk mengisi cangkir! Semakin banyak yang kumpulkan, semakin banyak kekuatan yang bisa aku peroleh!",
  str_guide_warn_80010205 = "Tapi tunggu... ada orang di depan pintu?",
  str_guide_circle_80010206 = "A-Apa itu?!",
  str_guide_circle_80010207 = "Tidak masalah... Saya tidak takut! Ketuk di sini, saya ingin pergi dan mencari tahu!",
  str_guide_warn_80010208 = "Aku ingin tahu siapa itu... Apakah mereka datang untukku?",
  str_guide_circle_80010304 = "Oh! Menemukannya, apakah itu... bayangan yang sama dari sebelumnya?",
  str_guide_warn_80010305 = "Bayangan itu bisa memanggil Eclipsites? Sekarang saya tidak bisa mengabaikannya begitu saja, bukan?",
  str_guide_warn_80010306 = "Guru saya mengatakan bahwa jika musuh terlalu kuat, jangan terlalu terjebak dalam pertarungan. Kamu bisa mencoba mengubah tingkat kesulitan!",
  str_guide_warn_80010307 = "Mimpi Buruk lebih menantang daripada Reverie, tetapi jika saya bisa menyelesaikan Mimpi Buruk dengan 3 bintang, saya bisa mendapatkan Ripples of Joy dan meningkatkan Smiles Lead to Happiness.",
  str_guide_warn_80010308 = "Setiap kali saya menghadapi Omen, Kecerdasan saya akan terpengaruh...",
  str_guide_warn_80010309 = "Tapi jangan khawatir! Saya rajin berolahraga agar tetap bugar, sehingga pada pukul 05:00 setiap hari, poin Wit akan pulih sebanyak 3 poin! Tapi begitu mencapai batas maksimum, itu tidak dapat ditingkatkan lebih jauh...",
  str_guide_circle_80010402 = "Ketemu!",
  str_guide_warn_80010403 = "Bagaimanapun, mari kita singkirkan untuk saat ini.",
  str_guide_warn_80010404 = "Setelah mengumpulkan begitu banyak barang, apakah akan ada reaksi magis di antara mereka?",
  str_guide_warn_80010405 = "Ah... aku hampir lupa, aku masih harus mengejar bayangan itu!",
  str_guide_warn_80010406 = "Geser layar untuk melihat sekeliling dengan baik!",
  str_guide_warn_80010407 = "Ketuk di sini untuk kembali ke tampilan awal.",
  str_guide_warn_80010408 = "Ada begitu banyak yang harus dilakukan, jadi lebih baik simpan informasinya di sini untuk saat ini.",
  str_guide_circle_80010501 = "Orang dewasa tidak pernah membiarkanku melewati gerbang ini... jadi satu-satunya cara adalah mendobraknya jika aku ingin keluar?",
  str_guide_circle_80010502 = "Kami akan mencari tahu.",
  str_guide_circle_80011101 = "A-Apa itu?! Apakah mereka mencoba membuat kekacauan di dunia ini... Humph, bukan berarti aku akan takut! Ketuk di sini, dan akan kusuruh mereka pergi secara langsung!",
  str_guide_warn_80010601 = "Aku menjadi lebih kuat? Pertempuran yang akan datang seharusnya sedikit lebih mudah sekarang.",
  str_guide_warn_80010701 = "Saya telah memperoleh kemampuan yang sama sekali baru? Saya akan mencobanya sebentar lagi!",
  str_guide_warn_80010121 = "Hah? Apa ini?",
  str_guide_warn_80010122 = "Wow, sepertinya aku telah menguasai kekuatan unik? Hehe, mari mencobanya! Kayaknya bisa digunakan satu kali setiap putaran bergantian!",
  str_guide_warn_80010521 = "Eh, kekuatanku telah berubah?",
  str_guide_warn_80010522 = "Pilih daerah? Itu sepertinya tidak sulit. Aku membantumu!",
  str_guide_warn_80010931 = "Menguasai kekuatan baru?",
  str_guide_warn_80010932 = "Baiklah, mari kita lakukan!",
  str_guide_warn_80011331 = "Kekuatanku telah berubah lagi...",
  str_guide_warn_80011332 = "Sepertinya saya sekarang dapat melepaskan kekuatan ini tanpa istirahat ...",
  str_guide_warn_80011631 = "Saya menguasai kekuatan lain!",
  str_guide_warn_80011632 = "Dengan kekuatan ini, saya tidak akan ragu lagi!",
  str_guide_warn_12300101 = "Sepertinya Anda senang dengan resor ini. Bisakah saya berbicara dengan Anda secara pribadi lalu?",
  str_guide_warn_12300201 = "Fasilitas tersebut telah menghasilkan Koin Pass baru lagi. Kamu perlu mengumpulkan dan menggunakannya untuk membentuk lingkaran kebajikan.",
  str_guide_warn_12300202 = "Koin Pass dari Distrik Hotel sudah siap untuk dikoleksi. Tugas asisten adalah mencari tahu cara menggunakannya secara efisien.",
  str_guide_warn_12300203 = "Kamu bertanya padaku bagaimana menggunakan Koin Pass? Cukup gunakan mereka untuk meningkatkan fasilitas secara langsung. Fasilitas yang ditingkatkan juga akan menghasilkan Koin Pass dengan lebih cepat. Inilah cara bisnis menggunakan uang untuk menghasilkan lebih banyak uang.",
  str_guide_warn_12300204 = "Kamu ingin tahu mengapa kamu tidak bisa mengumpulkan semua Koin Pass sekaligus? Ini karena pertimbangan keamanan. Hal utama adalah bahwa rasanya lebih meyakinkan untuk mengambilnya satu per satu dan memegangnya!",
  str_guide_warn_12300205 = "Masih ingat cara meng-upgrade fasilitas? Yuk, coba sekarang!",
  str_guide_warn_12300301 = "Untuk mengupgrade fasilitas, kamu memerlukan Koin Pass dan harus memenuhi syarat tertentu. Biar kulihat... Ya! Ini bisa diupgrade sekarang.",
  str_guide_warn_12300302 = "Fasilitas yang telah di-upgrade akan menjadi lebih populer dan dapat menghasilkan Pass Coins lebih efisien. Meng-upgrade fasilitas juga akan membuka petualangan dengan Aurorian lainnya dan meningkatkan reward.",
  str_guide_warn_12300303 = "Ketuk di sini untuk menandatangani rencana upgrade dan menyelesaikan peningkatan.",
  str_guide_warn_12300401 = "Sudah ditingkatkan sekarang! Saya juga telah mengumpulkan Koin Pass yang lupa Anda kumpulkan sebelumnya untuk Anda. Sama-sama!",
  str_guide_warn_12300501 = "Sepertinya kamu telah membuka petualangan bersama Aurorian lainnya. Mari kita periksa.",
  str_guide_warn_12300601 = "Sepertinya seorang gadis cantik, cerdas, lembut, dan menyenangkan sedang menunggumu.",
  str_guide_warn_12300701 = "Mengenai cara membuka petualangan bersama Aurorian... Saya rasa saya tidak perlu mengajari Anda tentang itu, kanan?",
  str_guide_warn_12300801 = "Kamu dapat melihat petualangan yang terbuka dan mengulas petualangan yang sudah kamu alami di Pemandu Petualangan.",
  str_guide_warn_12300802 = "Jika Anda memiliki pertanyaan tentang operasional resor, Anda bisa melihat buku panduan yang telah saya siapkan khusus untuk Anda.",
  str_guide_warn_12400101 = "Acara Valley Oasis telah dimulai! Selama Atraksi Siang Hari, kita akan menjelajahi berbagai fasilitas di dalam wonderland.",
  str_guide_warn_12400102 = "Selama Perayaan Malam, kita akan menghadapi tantangan yang lebih sulit di taman hiburan di bawah naungan kegelapan.",
  str_guide_warn_12400103 = "Di Park Tycoon, kami akan bertanggung jawab mengelola taman hiburan. Pastikan untuk merawatnya dengan baik!",
  str_guide_warn_12400104 = "Token Mesin Cakar yang diperoleh dengan menyelesaikan tahapan acara dan membelanjakan Prism dapat digunakan untuk menukarkan berbagai hadiah dari Mesin Cakar.",
  str_guide_warn_12400105 = "Ingatlah untuk masuk ke dalam game setiap hari untuk mendapatkan hadiah Konter Masuk Tamu.",
  str_guide_warn_12400106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_12400107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_12500101 = "Simfoni Kesuraman kini tersedia. Ayo selesaikan misi dari teman Illuminamu di gameplay Twilight Tactics dan bangun kembali kotanya!",
  str_guide_warn_12500102 = "Dalam gameplay On the Cusp of Gloom, kami akan mengirimkan tim pendahulu ke dalam penyelidikan di dekat zona senja untuk mengetahui rencana Eclipsite!",
  str_guide_warn_12500103 = "Ingatlah untuk masuk ke dalam game setiap hari untuk mendapatkan hadiah Masuk Kekuatan Baru.",
  str_guide_warn_12500104 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_12500105 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_10181401 = "Ketahanan Gerbang Benteng ditampilkan di sini. Luncurkan roket Anda saat Corrupted Engine VII mendekati Gerbang.",
  str_guide_circle_80010521_Lb = "Ini dia yang memegang boneka itu. Saat dikalahkan, itu memberikan kerusakan pada semua Eclipsites di lapangan dan secara acak mengoper boneka itu. Saat Eclipsite lain dikalahkan lebih dulu, pemegang boneka mendapatkan perisai hitungan.",
  str_guide_circle_80010521_LbT = "Penyebab Main-Main",
  str_guide_circle_80010521_Rb = "Kendalikan ilusi dengan Boneka!",
  str_guide_circle_80010521_RbT = "Boneka Sobek",
  str_guide_circle_80010621_Lt = "Pada awal pertempuran, Mata Jahat Hutan akan tertidur selama 3 putaran, dan Mata Jahat lainnya akan menghadapi penurunan DEF yang substansial selama waktu ini. Saat diserang, Mata Jahat akan terbangun.",
  str_guide_circle_80010621_LtT = "Rajin",
  str_guide_circle_80010621_Lb = "Sebelum kita pergi, izinkan saya istirahat dulu...",
  str_guide_circle_80010621_LbT = "Boneka Sobek",
  str_guide_circle_80010721_Lt = "Jika semua perisai hitungan tidak rusak di akhir putaran, musuh ini akan memberikan kerusakan tetap kepada pemain sekali.",
  str_guide_circle_80010721_LtT = "Kemarahan Narsistik",
  str_guide_circle_80010721_Rt = "Apakah ini... satu-satunya cara untuk menarik perhatianmu?",
  str_guide_circle_80010721_RtT = "Boneka Sobek",
  str_guide_circle_80010821_Lt = "Bos mengumpulkan energi setiap 3 putaran. Setiap tumpukan energi memberikan bonus ATK 3%. Jika semua tumpukan tidak dihapus hingga akhir putaran, bos akan mendapatkan 8 tumpukan count shield.",
  str_guide_circle_80010821_LtT = "Pegangan Besi",
  str_guide_circle_80010821_Rt = "Menerobos... sangkar... hanya untuk... membangunkanmu...",
  str_guide_circle_80010821_RtT = "Boneka Sobek",
  str_guide_circle_80010821_Rb = "Setiap kali bos diserang, 1 tumpukan tanda akan dihilangkan. Tanda energi ini secara signifikan meningkatkan ATK dan kemampuan bertahan bos, jadi sangat penting untuk menanganinya secepat mungkin!",
  str_guide_circle_80010821_RbT = "Strategi Melawan",
  str_guide_circle_80011021_Rt = "Semua musuh mendapatkan peningkatan ATK yang signifikan. Aurorian dapat memulihkan HP mereka dengan terus memberikan damage pada musuh.",
  str_guide_circle_80011021_RtT = "Serangan Balik Fana",
  str_guide_circle_80011021_Rb = "Apa perbedaan antara berhenti dan menyerah?",
  str_guide_circle_80011021_RbT = "\"Eve\"",
  str_guide_circle_80011121_Rt = "Tim dapat menggunakan Conveyor Vortex untuk berteleportasi ke mana saja di lapangan dan meluncurkan Chain Combo. Meningkatkan kerusakan Chain Combo.",
  str_guide_circle_80011121_RtT = "Kombo Gratis",
  str_guide_circle_80011121_Rb = "Ikut denganku. Anda dapat pergi ke mana pun Anda inginkan.",
  str_guide_circle_80011121_RbT = "\"Eve\"",
  str_guide_circle_80011421_Rt = "Pembuatan rune tidak efisien, dan Shadow sekarang akan langsung memanggil Shadowgeist.",
  str_guide_circle_80011421_RtT = "Karakteristik Musuh",
  str_guide_circle_80011421_Rb = "Saat menghubungkan ubin, kerusakan Aurorian yang diberikan akan sangat meningkat, termasuk serangan normal dan efek kerusakan tambahan.",
  str_guide_circle_80011421_RbT = "Karakteristik Tim",
  str_guide_circle_80011521_Rt = "Kalahkan Enferno untuk menyelesaikan stage. Spellhound akan terus respawning sebelum Enferno dikalahkan.",
  str_guide_circle_80011521_RtT = "Karakteristik Musuh",
  str_guide_circle_80010921_Lb = "Semua Eclipsites yang hadir dapat respawn satu kali. Saat Eclipsite mati, semua Eclipsite yang tersisa di lapangan menerima peningkatan ATK.",
  str_guide_circle_80010921_LbT = "Karakteristik Musuh",
  str_guide_circle_80010921_Rb = "Semakin keras kau berjuang, semakin sakit.",
  str_guide_circle_80010921_RbT = "\"Eve\"",
  str_guide_circle_80011321_Lb = "Jumlah tumpukan Penetrability Mark akan meningkat secara signifikan dengan kemampuan musuh, tetapi setiap serangan pemain akan mengurangi Penetrability Mark sebanyak satu tumpukan.",
  str_guide_circle_80011321_LbT = "Karakteristik Musuh",
  str_guide_circle_80011321_Rb = "Efek negatif Penetrability Mark sangat meningkat. Pastikan untuk mengurangi jumlah Penetrability Marks dengan menyerang musuh secepat mungkin!",
  str_guide_circle_80011321_RbT = "Strategi Melawan",
  str_guide_circle_80011621_Lb = "Mulai dari tahap ini, tim mendapatkan entri khusus. Setiap kali musuh menerima kerusakan sebelum tim menghubungkan petak, serangan semua Aurorian dalam tim meningkat sebesar 1% untuk putaran itu!",
  str_guide_circle_80011621_LbT = "Pertumbuhan Terakhir",
  ["str_guide_circle_CN2-18_Lt"] = "Rasa sakit karena isolasi dan ketakutan akan terputus, kenangan masa lalu yang tak tertahankan itu, telah membentuk orang yang dikenal sebagai Eve Hari ini.",
  ["str_guide_circle_CN2-18_LtT"] = "Berduka Eve",
  ["str_guide_circle_CN2-18_Rt"] = "Di awal setiap putaran, panggil a Dawn Berbunga di lokasi yang ditentukan untuk memulihkan HP; setiap Dawn Bunga memberikan dorongan pemulihan ekstra.",
  ["str_guide_circle_CN2-18_RtT"] = "Karakteristik Musuh",
  ["str_guide_circle_CN2-18_Rb"] = "Pada putaran tertentu, Eve akan menerima sejumlah besar tumpukan kekebalan. Sangat penting untuk mengurangi tumpukan ini sebanyak mungkin melalui kerusakan frekuensi tinggi; jika tidak, pada putaran berikutnya, jumlah HP yang cukup besar akan dipulihkan berdasarkan jumlah tumpukan yang tersisa.",
  ["str_guide_circle_CN2-18_RbT"] = "Deskripsi Keahlian",
  str_guide_circle_N34_18_1_RtT = "Medik Illumina",
  str_guide_circle_N34_18_1_Rt = "Di mana pun Medik Illumina berdiri, semangat meningkat, karena rekan-rekan tahu bahwa luka mereka tidak akan dibiarkan tanpa perawatan. Illumina Federation, yang sangat menyadari hal ini, memberikan perlindungan yang ditingkatkan kepada medik-medik ini, sehingga meningkatkan kemampuan bertahan hidup mereka secara signifikan.",
  str_guide_circle_N34_18_1_LbT = "Monster Trait",
  str_guide_circle_N34_18_1_Lb = "Seorang Prajurit Illumina tanpa kemampuan bertarung. Mengembalikan HP untuk Prajurit Illumina terdekat dan memulihkan sebagian Memar mereka sendiri.",
  str_guide_circle_N34_18_1_RbT = "Awas!",
  str_guide_circle_N34__18_1_Rb = "Saat menerima damage, Illumina Medik akan mengumpulkan Memar setara dengan 50% dari damage yang diterima. Selain itu, DEF mereka akan meningkat seiring berkurangnya HP.",
  str_guide_circle_N34_18_2_RtT = "Penyiar Sinyal Illumina",
  str_guide_circle_N34_18_2_Rt = "Dilengkapi dengan komunikator kompak, Signalman Illumina menanggung beban berat. Oleh karena itu, Illumina Federation telah mengembangkan perangkat pendukung khusus, yang memfasilitasi transmisi sinyal mereka saat bergerak, yang merupakan asal dari nama unit ini.",
  str_guide_circle_N34_18_2_LbT = "Monster Trait",
  str_guide_circle_N34_18_2_Lb = "Seorang Prajurit Illumina tanpa kemampuan bertarung tetapi mampu memanggil bala bantuan Illumina ke medan perang.",
  str_guide_circle_10170901_RtT = "Dreadweaver",
  str_guide_circle_10170901_Rt = "Didorong oleh obsesi untuk melenyapkan segalanya, ia mengabaikan pelepasan energi sendiri, tanpa henti mengejar tujuan, meskipun itu berarti perlahan-lahan menuju kehancuran dirinya sendiri.",
  str_guide_circle_10170901_LbT = "Detail Pasif",
  str_guide_circle_10170901_Lb = "Setiap kali pergerakan tim berakhir, Dreadweaver akan segera membuat tim mengubah posisi mereka, yang mempengaruhi penggunaan Chain Combo.",
  str_guide_circle_10170901_RbT = "Karakteristik serangan",
  str_guide_circle_10170901_Rb = "Ketika HP Dreadweaver turun di bawah 50%, ia akan memulai ritual pengorbanan. Pada putaran berikutnya, ia akan membakar hampir seluruh HP-nya, memberikan kerusakan nyata besar pada pemain. Efek ini hanya dapat diaktifkan sekali.",
  str_guide_circle_2002901_RtT = "Tangki Illumina L5",
  str_guide_circle_2002901_Rt = "Dibuat melalui modifikasi truk, Tank Illumina L5 memiliki baju besi ringan yang cocok untuk produksi massal. Kemampuan pengisian daya dan meriam tembakan cepatnya membuat unit ringan musuh dapat dihancurkan dengan cepat.",
  str_guide_circle_2002901_LbT = "Karakteristik Musuh",
  str_guide_circle_2002901_Lb = "Berdasarkan posisi musuh, pilih antara menembakkan hujan peluru dengan cepat atau melakukan serangan terburu-buru.",
  str_guide_circle_2003001_RtT = "Pemantik Api Illumina",
  str_guide_circle_2003001_Rt = "\"Reduksi semua lawan menjadi abu\" - Mereka melambangkan efisiensi dan keganasan pasukan Illumina. Di hadapan api yang mengamuk, semua kehidupan berdiri sejajar.",
  str_guide_circle_2003001_LbT = "Karakteristik Musuh",
  str_guide_circle_2003001_Lb = "Mengumpulkan Memar saat menerima kerusakan. Menimbulkan damage pada semua target dalam jangkauan serangan, mengakibatkan Burn pada mereka dan menciptakan api.",
  str_guide_circle_2003401_RtT = "Prajurit Illumina yang Terkorupsi",
  str_guide_circle_2003401_Rt = "Dulu sekutu, kini musuh—begitulah ketakutan akan Eclipse. Belas kasihan yang tersisa hanyalah untuk menenangkan mereka.",
  str_guide_circle_2003401_LbT = "Karakteristik Musuh",
  str_guide_circle_2003401_Lb = "Jika HP di bawah 40% di awal ronde, unit tersebut memiliki ACT dan DEF yang meningkat serta gaya serangan yang berubah.",
  str_guide_circle_2003101_RtT = "Sersan Illumina",
  str_guide_circle_2003101_Rt = "Sebagai perwira tingkat dasar dari tentara Illumina, mereka bertanggung jawab untuk memimpin prajurit biasa di medan perang. Sebagian besar dari mereka lulusan dari akademi militer, sementara beberapa yang terpilih dipromosikan dari jajaran veteran berpengalaman.",
  str_guide_circle_2003101_LbT = "Karakteristik Musuh",
  str_guide_circle_2003101_Lb = "Kehadiran mereka meningkatkan kemampuan Prajurit Illumina di sekitar dan membantu mereka pulih dari Luka memar. Jika mereka terpisah dari sekutu atau berada dalam jarak dekat dengan musuh, sersan ini mengambil senjata, menimbulkan kerusakan dengan potongan mematikan dan tendangan berdampak.",
  str_guide_circle_2003101_RbT = "Strategi Melawan",
  str_guide_circle_2003101_Rb = "Kalahkan komandan musuh terlebih dahulu!",
  str_guide_circle_2905701_RtT = "Mudbundle",
  str_guide_circle_2905701_Rt = "Konon diciptakan oleh anggota Eclipse, Eclipsite ini merupakan fusi dari berbagai sifat biologis. Ia menciptakan rawa-rawa mengerikan yang dapat melahap segala sesuatu dan mengkontaminasi apa pun yang disentuhnya.",
  str_guide_circle_2905701_LbT = "Karakteristik Musuh",
  str_guide_circle_2905701_Lb = "Menciptakan rawa dan tenggelam di dalamnya, menghalangi dan mengganggu pergerakan Aurorian di dalamnya, mengubah medan.",
  str_guide_circle_2905701_RbT = "Strategi Melawan",
  str_guide_circle_2905701_Rb = "Hindari melewati terlalu banyak rawa-rawa. Gunakan kemampuanmu untuk membersihkan lapangan!",
  str_guide_circle_29057011_RtT = "Quagmire",
  str_guide_circle_29057011_Rt = "Mengkontaminasi semua yang telah dilihat...",
  str_guide_circle_29057011_LbT = "Karakteristik",
  str_guide_circle_29057011_Lb = "Melewati sejumlah rawa tertentu akan meningkatkan cooldown Skill Aktif semua Aurorian.",
  str_guide_circle_29057011_RbT = "Strategi Melawan",
  str_guide_circle_29057011_Rb = "Dapat dibersihkan oleh Skill Area Damage Aurorian",
  str_guide_warn_815000101 = [[
Mengapa saya masih belum bisa bebas dari mimpi ini? Apakah karena Paloma... apakah dia masih terjebak di dalamnya?
Tekan tombol Switch untuk beralih ke Mode Roam. Navigator, bisakah kamu membantu Paloma seperti cara kamu membantuku?]],
  str_guide_warn_815000102 = "Ketuk tombol Switch lagi untuk kembali ke Mode Unveil. Navigator, sepertinya kita bisa kembali ke mimpi saya kapan saja yang kita inginkan!",
  str_guide_circle_80020201 = "Ketuk timbangan di sini untuk membantu saya melakukan kontemplasi dan deduksi yang lebih mendalam. Hanya setelah menyelesaikan deduksi saya, saya dapat melanjutkan tugas-tugas yang diberikan oleh Hakim Kepala.",
  str_guide_circle_80020202 = "Namun, sebelum memulai penyimpulan, saya harus mengumpulkan cukup bukti, kesaksian... Amati dengan cermat. Petunjuk penting pasti ada di sekitar!",
  ["str_guide_circle_CN5-15_Lt"] = "Mewarisi ajaran sungguh-sungguh dari ayahnya dan memenuhi semua harapannya, ia telah menjadi Irridon yang sempurna, Chief Judge terhebat yang pernah dikenal!",
  ["str_guide_circle_CN5-15_LtT"] = "Irridon: Eximius",
  ["str_guide_circle_CN5-15_Rt"] = "Sebelum setiap Chain Combo, membentuk Shield of Light, yang memblokir damage sebanding dengan persentase HP Maks.",
  ["str_guide_circle_CN5-15_RtT"] = "Perisai Cahaya",
  ["str_guide_circle_CN5-15_Lb"] = "Mengendalikan dan menipu orang lain dengan klon-klonnya—trik-trik ini hampir tidak tercela di matanya; bagaimanapun, dia memiliki wewenang tertinggi sebagai Chief Judge terhebat.",
  ["str_guide_circle_CN5-15_LbT"] = "Irridon: Klon Eximius",
  ["str_guide_circle_CN5-15_Rb"] = "Kerusakan yang diberikan kepada Irridon: Klon Eximius langsung ditransfer ke Irridon: Eximius.",
  ["str_guide_circle_CN5-15_RbT"] = "Transmisi Kerusakan",
  ["str_guide_circle_CN5-18_Lb"] = "Berada di luar lapangan, kebal terhadap serangan normal, hanya bisa diserang oleh skill target tunggal.",
  ["str_guide_circle_CN5-18_LbT"] = "Irridon: Klon Eximius",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "Patung bangsawan yang sombong. Menimbulkan 1 tumpukan Prejudice pada sekutu dan hancur saat disentuh, mengubah ubin tempat mereka berada menjadi ubin berwarna sambil menghapus 1 tumpukan Prejudice.",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "Patung Anggota Juri",
  ["str_guide_circle_CN5-4_Rb"] = "Musuh tertentu memiliki efek Shield of Light. Sebelum setiap Chain Combo, mereka membentuk Shield of Light, yang menghalangi damage sebesar persentase dari HP Maks mereka.",
  ["str_guide_circle_CN5-4_RbT"] = "Perisai Cahaya",
  ["str_guide_circle_CN5-8_Lt"] = "Kesombongan, prasangka, dan pikiran yang rusak... telah membeku menjadi hantu jahat yang berkeliaran di Lumopolis, meresap ke setiap celah kota abadi ini.",
  ["str_guide_circle_CN5-8_LtT"] = "Crimson Specter",
  ["str_guide_circle_CN5-8_Lb"] = "Ia dapat teleportasi ke lokasi pemain terdekat, memberikan beberapa serangan yang merusak dan mendorong pemain ke belakang. Semakin jauh ia teleportasi, semakin sedikit serangan yang diluncurkan.",
  ["str_guide_circle_CN5-8_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_CN5-8_Rb"] = "Crimson Specter dapat mengacaukan posisi pemain, jadi disarankan untuk segera mengeliminasinya atau menjauh darinya.",
  ["str_guide_circle_CN5-8_RbT"] = "Strategi Melawan",
  ["str_guide_circle_n35-7_LtT"] = "Binatang Rime",
  ["str_guide_circle_n35-7_Lt"] = "Dengan bulu dan cakar tajam, jenis Eclipsites ini sangat mirip dengan binatang buas, membuat mereka sangat cocok untuk menyusup ke berbagai wilayah perbatasan untuk melacak, mengintai, dan berburu.",
  ["str_guide_circle_n35-7_Lb"] = "Ini memilih skill berbeda berdasarkan posisi Aurorian, dan jika serangannya tidak dapat mencapai Aurorian mana pun, ia akan memilih untuk memulihkan HP-nya sendiri.",
  ["str_guide_circle_n35-7_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_n35-7_Rb"] = "Perhatikan jangkauan serangan Eclipsite, dan selalu waspadai posisi sekutu kita!",
  ["str_guide_circle_n35-7_RbT"] = "Strategi Melawan",
  ["str_guide_circle_n35-9_LtT"] = "No. 33",
  ["str_guide_circle_n35-9_Lt"] = "Seorang Aurorian dari masa lalu yang jauh, bertugas menjaga reruntuhan bawah tanah Northland. Echo Template-nya terus menghasilkan kesalahan karena kerusakan yang dialaminya dan aktivasi yang tidak lazim.",
  ["str_guide_circle_n35-9_Lb"] = "Mampu melakukan teleportasi dan mengacaukan susunan ubin serta menyerap energi ubin untuk menyerang Aurorian. Semakin banyak ubin yang tersedia untuk menyerap energi, semakin tinggi kerusakannya.",
  ["str_guide_circle_n35-9_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_n35-9_Rb"] = "Perhatikan distribusi tile di medan tempur dan waspadai saat musuh menggunakan keterampilan!",
  ["str_guide_circle_n35-9_RbT"] = "Strategi Melawan",
  str_guide_circle_n35_trap5352031_RtT = "Bom Mematikan",
  str_guide_circle_n35_trap5352031_Rt = "Meledak setiap kali waktu tertentu telah berlalu, menimbulkan damage pada semua unit di medan perang.",
  str_guide_circle_n35_trap5352031_RbT = "Strategi Melawan",
  str_guide_circle_n35_trap5352031_Rb = "Perintahkan Aurorianmu untuk mengalahkan musuh secepatnya, atau kamu akan menerima damage seiring berjalannya waktu.",
  str_guide_warn_53540034 = "Tampil di sini adalah hitung mundur yang tersisa untuk Realm.",
  str_guide_warn_16000101 = "Enigma yang Disegel dalam Es kini tersedia! Saatnya bertemu mitra baru dan memulai petualangan dalam ekspedisi Through the Snow!",
  str_guide_warn_16000102 = "Di Fatal Trek, kita akan menghadapi serangkaian tantangan yang lebih kompleks.",
  str_guide_warn_16000103 = "Di event Ancient Yurt, kita bisa menukarkan Ancient Remains dengan Solamber, Aurorian bintang 5, dan item berharga lainnya. Peninggalan Kuno dapat diperoleh dengan menyelesaikan tahapan acara dan mengonsumsi Prism.",
  str_guide_warn_16000104 = "Mode Lemari Zarya yang baru akan tersedia. Ketuk pintu masuk mode gameplay baru ini untuk menjelajahinya!",
  str_guide_warn_16000105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_16000106 = "Jangan lupa login ke game setiap hari untuk memperoleh reward login harian.",
  str_guide_warn_16000107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_9700101 = "Daftar Keinginan tersedia dalam rekrutmen waktu terbatas ini. Ketuk untuk membuka antarmuka Daftar Keinginan.",
  str_guide_warn_9700106 = "Daftar Keinginan tersedia secara eksklusif dalam rekrutmen yang dimilikinya.",
  str_guide_warn_9700107 = "Dalam rekrutmen ini, ada Aurorian yang memiliki peluang perolehan lebih besar yang ditetapkan di posisi teratas Daftar Keinginan, mengambil peluang 50% di semua Aurorian bintang 6 yang tersedia.",
  str_guide_warn_9700108 = "Pilih satu Aurorian bintang 6 dari masing-masing empat elemen, dan masing-masing elemen akan memiliki peluang 12,5% untuk mendapatkan Aurorian Bintang 6.",
  ["str_guide_circle_n36-9_LtT"] = "Emperor of Demise",
  ["str_guide_circle_n36-9_Lt"] = "Kaisar Tertinggi Kekacauan, ayah dari Tohru, seorang veteran dalam banyak perang, adalah kekuatan yang tak terbantahkan kapan pun dan di mana pun.",
  ["str_guide_circle_n36-9_Lb"] = "Dengan kekuatan yang tangguh, ia menguasai berbagai skill untuk menargetkan pemain dengan presisi atau melancarkan serangan jarak luas, sekaligus mendorong mereka mundur.",
  ["str_guide_circle_n36-9_LbT"] = "Karakteristik Musuh",
  ["str_guide_circle_n36-9_Rb"] = "Kaisar Kehancuran bisa dipengaruhi oleh kemampuan knockback atau teleportasi dari pemain. Memindahkannya pada saat yang tepat memungkinkan pemain untuk menghindari atau mengganggu serangan yang dilancarkannya.",
  ["str_guide_circle_n36-9_RbT"] = "Strategi Melawan",
  str_guide_warn_17000101 = "Dragon Maid's Break kini tersedia! Saatnya bertemu teman baru dan memulai petualangan baru di The Road Home!",
  str_guide_warn_17000102 = "Gunakan Prism di stage utama dan stage Resource Raid untuk Dinner Plate.",
  str_guide_warn_17000103 = "Gunakan Dinner Plate untuk menerima berbagai hadiah di Dapur Tohru.",
  str_guide_warn_17000104 = "Selama acara, ikuti A Caelestite Tea Party untuk kuis keakraban dengan Aurorian!",
  str_guide_warn_17000105 = "Jangan lupa login ke game setiap hari dan dapatkan sign-in reward.",
  str_guide_warn_17000106 = "Ikuti serangkaian tantangan event dan tuntaskan quest dalam Special Event Book!",
  str_guide_warn_17000107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_18000101 = "Venom Flows Through Corrupted Hearts kini tersedia! Saatnya bertemu teman baru dan memulai petualangan baru di Underground Clinic!",
  str_guide_warn_18000102 = "Di Masa Kelam, kita akan menghadapi serangkaian tantangan yang lebih kompleks.",
  str_guide_warn_18000103 = "Dapatkan Collection Jars yang bisa ditukarkan dengan berbagai Reward di The Secret Room dengan menyelesaikan Event Stage dan memakai Prism.",
  str_guide_warn_18000104 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_18000105 = "Jangan lupa login ke game setiap hari untuk memperoleh reward login harian.",
  str_guide_warn_18000106 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  ["str_guide_circle_CN7-15_Lt"] = "Dari dunia permukaan ke kota bawah air, seorang bangsawan yang arogan dan jahat.",
  ["str_guide_circle_CN7-15_LtT"] = "Raja Merman",
  ["str_guide_circle_CN7-15_Rt"] = "Serangan menimbulkan efek knockback. Dapat memanggil meriam salvo di tepi medan perang.",
  ["str_guide_circle_CN7-15_RtT"] = "Karakteristik Musuh",
  ["str_guide_circle_CN7-15_Lb"] = "Perhatikan jangkauan serangan meriam salvo di sekitar medan perang. Kalahkan artileri secara tepat waktu untuk mengakhiri pertempuran dengan cepat.",
  ["str_guide_circle_CN7-15_LbT"] = "Strategi Melawan",
  ["str_guide_circle_CN7-5_Lt"] = "Eclipsite yang menyerupai laras senjata. Memberikan dukungan kepada teman-temannya dan menyerang tim Anda dengan keras!",
  ["str_guide_circle_CN7-5_LtT"] = "Senapan Salvo",
  ["str_guide_circle_CN7-5_Rt"] = "Menembak musuh dalam jangkauan serangan. Jika tidak ada target yang tersedia, serangannya ditingkatkan dan menyembuhkan Raja Merman.",
  ["str_guide_circle_CN7-5_RtT"] = "Meriam Berat",
  ["str_guide_circle_CN7-7_Lt"] = "Sekutu tidak dapat terhubung melaluinya, begitu juga dengan unit musuh di darat, tetapi hal ini tidak akan mempengaruhi efek dari kemampuan yang digunakan.",
  ["str_guide_circle_CN7-7_LtT"] = "Dinding Terlarang",
  str_guide_circle_80030101 = "Dengan teropong, kamu dapat melihat kastil megah di kejauhan—kuil dari Aqua Lord.",
  str_guide_warn_80030102 = "Ketuk tombol Konstruksi Kuil dan Connolly akan menuju ke tempat dengan pemandangan kuil yang sempurna, bersama dengan tentakelnya yang tepercaya, untuk melanjutkan proyek restorasi kuil.",
  str_guide_warn_80030301 = "Navigator, selamat datang di Ritual Fusi! Letakkan Aqua Shard di area fusi yang berada di tengah Ritual Fusi untuk membantu saya menyelesaikan ritual, mengembalikan kekuatan Antons!",
  str_guide_warn_80030302 = "Aqua Shard mengandung kekuatan Anton. Setiap Shard memiliki jumlah kekuatan fusi yang berbeda. Di bawah kondisi tertentu, beberapa shard mungkin akan melepaskan kekuatan tambahan.",
  str_guide_warn_80030303 = "Seret Pecahan Aqua ke tempat yang memenuhi syarat di area fusi. Setelah berhasil ditempatkan, Ritual Fusi akan memandu dan mengekstrak kekuatan fusi di dalamnya.",
  str_guide_warn_80030304 = "Setelah berhasil meletakkan Aqua Shard, Anda dapat mengetuk untuk memilih dan memindahkan atau menyesuaikannya. Jelajahi penempatan yang berbeda untuk menghasilkan lebih banyak kekuatan agregasi.",
  str_guide_warn_80030305 = "Saat dipilih, ketuk tombol Putar untuk memutar serpihan berlawanan arah jarum jam sebesar 90 derajat.",
  str_guide_warn_80030306 = "Saat dipilih, ketuk tombol Batal untuk mengambil kembali Shard-nya.",
  str_guide_warn_80030307 = "Di sini, Anda akan menemukan total kekuatan fusi yang terkandung dalam Aqua Shard yang saat ini ditempatkan dan kekuatan fusi yang diperlukan untuk menyelesaikan Ritual Fusi ini!",
  str_guide_warn_80030308 = "Ketuk tombol Hapus untuk menghilangkan semua Aqua Shard yang ditempatkan. Berhati-hatilah!",
  str_guide_warn_80030309 = "Ketika kekuatan fusi memenuhi persyaratan untuk Ritual Fusi, tekan tombol Selesai untuk menyelesaikan ritual dan mengembalikan kekuatan Anton!",
  str_guide_warn_18100101 = "Tolong bantu lihat bersamaku! Apa yang sedang terjadi di sini!",
  str_guide_warn_18100102 = "Di sinilah Anda dapat memulai latihan Anda! Selesaikan tahap latihan untuk mendapatkan poin dan hadiah tahap!",
  str_guide_warn_18100103 = "Perlu Dicatat: Selama modul pelatihan, ikatan ada di antara beberapa Aurorian. Ketika Aurorian yang memiliki ikatan dikerahkan bersamaan, mereka akan mendapatkan lebih banyak kesempatan untuk terlibat dalam pertempuran.",
  str_guide_warn_18100104 = "Saat setidaknya 3 Aurorian dari faksi yang ditentukan dikerahkan, menghapus beberapa ubin sekaligus saat latihan dapat mengaktifkan kemampuan dukungan faksi.",
  str_guide_warn_18100105 = "Menyelesaikan pelatihan akan memberimu poin, dan setelah kamu mencapai jumlah poin tertentu per sesi, kamu akan mendapatkan hadiah spesial.",
  str_guide_warn_18100106 = "Menyelesaikan tahap pelatihan akan memberi kamu hadiah. Jumlah maksimum hadiah yang bisa kamu dapatkan setiap sesi akan ditampilkan di sini.",
  str_guide_warn_18100107 = "Jika ada pertanyaan, kamu bisa melihat deskripsi lengkapnya di sini.",
  str_guide_warn_18100108 = "Jumlah total putaran dalam setiap siklus latihan terbatas, dan total HP tim dari stage ke stage akan diakumulasikan.",
  str_guide_circle_N37boss_Lt = "Pembuluh darahnya berdenyut dengan racun merah darah, siap untuk membasmi ancaman apa pun terhadap keluarganya, termasuk dirinya sendiri.",
  str_guide_circle_N37boss_LtT = "Rebecca Rawa Beracun",
  str_guide_circle_N37boss_Rt = "Memberikan efek Fusion, menyebabkan target yang terkena efek kehilangan HP di awal putaran mereka.",
  str_guide_circle_N37boss_RtT = "Karakteristik Musuh",
  str_guide_circle_N37boss_Lb = "Manfaatkan sepenuhnya Ubin Gelap yang diubah oleh Tanda Racun dan berikan damage pada saat yang tepat.",
  str_guide_circle_N37boss_LbT = "Strategi Melawan",
  str_guide_circle_N37cap_Lt = "Pemimpin geng yang berpenampilan aneh, ahli dalam senjata api. Kehadirannya hanya menimbulkan masalah bagi Umbraton.",
  str_guide_circle_N37cap_LtT = "Kapten Geng",
  str_guide_circle_N37cap_Rt = "Menyerang setelah menjauh dari target, menimbulkan damage 2 kali. Dapat mencuri atribut target.",
  str_guide_circle_N37cap_RtT = "Karakteristik Musuh",
  str_guide_circle_N37cap_Lb = "Perhatikan jarak di antara dan kalahkan musuh tepat waktu.",
  str_guide_circle_N37cap_LbT = "Strategi Melawan",
  str_guide_circle_N37ranger_Lt = "Akurat, aman, diskret, dan sangat kuat, busur silang telah menjadi senjata yang disukai oleh gangster karena sifat-sifat tak tertandingi ini. Musuh yang ahli dalam penggunaannya sering kali sangat berbahaya.",
  str_guide_circle_N37ranger_LtT = "Pemanah Gangster",
  str_guide_circle_N37ranger_Rt = "Dapat menyerang target dalam bentuk silang hingga batas maksimum jangkauannya. Setelah mengenai, mengurangi penyembuhan yang diterima target.",
  str_guide_circle_N37ranger_RtT = "Karakteristik Musuh",
  str_guide_circle_N37ranger_Lb = "Mendekat dengan cepat dan prioritaskan untuk menghabisi mereka.",
  str_guide_circle_N37ranger_LbT = "Strategi Melawan",
  str_guide_circle_N37light_Lt = "Anggota geng yang besar dan kuat, ahli dalam menggunakan lengan mekaniknya untuk bertarung. Selain itu, dia dapat memberikan dukungan kepada pasukan musuh Umbraton lainnya di medan perang.",
  str_guide_circle_N37light_LtT = "Spesialis Dukungan Geng",
  str_guide_circle_N37light_Rt = "Memberikan peningkatan ATK untuk anggota Umbraton dalam 1 cluster sekitarnya; menyembuhkan diri sendiri ketika HP mereka turun di bawah persentase tertentu.",
  str_guide_circle_N37light_RtT = "Karakteristik Musuh",
  str_guide_circle_N37light_Lb = "Hilangkan mereka sekaligus untuk mencegah penyembuhan diri yang terus-menerus.",
  str_guide_circle_N37light_LbT = "Strategi Melawan",
  str_guide_circle_n37_trap2803501_RtT = "Tile Gelap",
  str_guide_circle_n37_trap2803501_Rt = "Ubin berikutnya di lokasi ini dijamin akan memiliki elemen yang sama dengan ubin saat ini.",
  str_guide_circle_n37_trap2803501_RbT = "Strategi Melawan",
  str_guide_circle_n37_trap2803501_Rb = "Gunakan skill tile-converting untuk mengubah elemen tile agar efeknya maksimal.",
  str_guide_circle_N37cike_LtT = "Pembunuh Geng",
  str_guide_circle_N37cike_Lt = "Meluncurkan 2 serangan berturut-turut yang cepat terhadap musuh dan mencuri atribut target.",
  str_guide_circle_N37cike_Lb = "Kalahkan musuh secepat mungkin. Jangan biarkan mereka menyerang Anda terus-menerus.",
  str_guide_circle_N37cike_LbT = "Strategi Melawan",
  str_guide_warn_551105 = "Ketuk di sini!",
  str_guide_warn_551106 = "Sistem Pencerahan telah diaktifkan. Atribut Aurorian kini dapat ditingkatkan secara komprehensif. Ketuk untuk masuk ke Modul Air.",
  str_guide_warn_551107 = "Daftar di sebelah kiri memungkinkan Anda untuk cepat beralih antara Modul dari berbagai Elemen.",
  str_guide_warn_551108 = "Lihat level dan progres Modul Elemen ini di sini.",
  str_guide_warn_551109 = "Lihat detail peningkatan modul di sini.",
  str_guide_warn_551110 = "Jika ada pertanyaan, kamu bisa melihat deskripsi lengkapnya di sini.",
  str_guide_warn_19000101 = "Di sini, Anda dapat menyelamatkan harta karun, mengambil peninggalan berharga dari kapal-kapal yang tenggelam satu per satu kembali ke permukaan.",
  str_guide_warn_19000102 = "Relik yang ditemukan akan didokumentasikan dalam Arsip Relik ini. Buka untuk mengakses catatan terkait.",
  str_guide_warn_19000103 = "Jika ada pertanyaan, jangan ragu untuk melihat instruksi bantuan di sini untuk penjelasan.",
  str_guide_warn_19000104 = "Ketuk pada Relic di lapangan untuk memindahkannya ke area penyelamatan di bawah.",
  str_guide_warn_19000105 = "Ketika jumlah relik yang identik di area penyelamatan mencapai 3, relik akan berhasil diselamatkan dan dihapus dari slot.",
  str_guide_warn_19000106 = "Di sini, gunakan fungsi penyimpanan relic untuk memindahkan relic dari slot penyelamatan ke lapangan, mencegah kegagalan karena semua slot terisi.",
  str_guide_cage_Rt = "Dapat dihancurkan oleh Skill Area Damage Aurorian. Musuh baru mungkin muncul setelah dihancurkan!",
  str_guide_cage_RtT = "Jebakan Spesial - Sangkar",
  str_guide_circle_N38boss_Lt = "Senjata berbahaya yang diciptakan dengan menggabungkan karakteristik mematikan dari berbagai ciptaan mekanis, termasuk teknologi dari Astra. Sumber daya listrik biasa tidak mampu menjalankan makhluk raksasa ini.",
  str_guide_circle_N38boss_LtT = "Stinger: Koalesensi",
  str_guide_circle_N38boss_Rt = "Setiap Clockwork Beast yang membentuk bagian tubuhnya memiliki serangan unik tersendiri. Ekor dapat mengumpulkan Energi untuk memberikan kerusakan yang pasti pada targetnya, tetapi juga cukup rapuh.",
  str_guide_circle_N38boss_RtT = "Karakteristik Musuh",
  str_guide_circle_N38boss_Lb = "Serang ekornya dengan Sniper Aurorian terlebih dahulu untuk membuatnya sementara tidak dapat bergerak, lalu manfaatkan kesempatan ini untuk memberikan damage.",
  str_guide_circle_N38boss_LbT = "Strategi Melawan",
  str_guide_warn_13800101 = [[
Terukir di Lautan Drifting Begonia I kini tersedia!
Saatnya bertemu teman-teman baru dan memulai petualangan baru di The Homecoming!]],
  str_guide_warn_13800102 = "Gunakan Prism di tahap cerita utama dan tahap Resource Raid untuk mendapatkan Promissory Note Lin Guild.",
  str_guide_warn_13800103 = "Di Lost Ship At Sea, kita akan menghadapi serangkaian tantangan yang lebih kompleks.",
  str_guide_warn_13800104 = "Di The Docks, gunakan Promissory Note Lin Guild untuk menukarkan berbagai hadiah.",
  str_guide_warn_13800105 = "Jangan lupa login ke game setiap hari untuk memperoleh reward Berth Sign-In.",
  str_guide_warn_13800106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_13800107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_crab_Rt = "Penciptaan alat mekanis ini dirancang untuk membantu pengrajin membuat penemuan yang cerdas. Kemudian, alat ini dimodifikasi sehingga variasi dari penemuan ini bisa menyimpan Flame Force di perutnya. Alat ini tidak pernah dimaksudkan untuk digunakan sebagai senjata.",
  str_guide_crab_RtT = "Kepiting yang Ditempa di Tungku",
  str_guide_crab_Lt = "Bergerak secara lateral sambil memuntahkan api untuk menyerang target di depannya.",
  str_guide_crab_LtT = "Karakteristik Musuh",
  str_guide_crab_Lb = "Kepiting yang Dibentuk Furnace memiliki pola gerakan yang tetap dan tidak bisa berbalik, jadi berada di belakangnya sebelum kamu mulai memberikan damage.",
  str_guide_crab_LbT = "Strategi Melawan",
  str_guide_warn_13900101 = [[
Shadows Beneath the Gloom kini tersedia!
Saatnya bertemu teman baru dan memulai petualangan baru di Under the Shadows!]],
  str_guide_warn_13900102 = "Gunakan Prism di tahap cerita utama dan tahap Resource Raid untuk mendapatkan Token Cloudrover.",
  str_guide_warn_13900103 = "Di Deadly Arena, kita akan menghadapi serangkaian tantangan yang lebih kompleks.",
  str_guide_warn_13900104 = "Di Airship Cloudrover, gunakan Token Cloudrover untuk menukarkan berbagai hadiah.",
  str_guide_warn_13900105 = "Jangan lupa login ke game setiap hari untuk memperoleh reward Sign-In Pengunjung.",
  str_guide_warn_13900106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_13900107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_circle_S4boss_Lt = "Sebuah pedang yang terampil dibuat dari kecerdasan Kerajaan Ye di Longzhou. Awalnya ditujukan sebagai senjata pertahanan diri bagi mereka yang tidak tahu cara membela diri dengan pedang, tetapi sekarang telah menjadi pedang jahat yang terkutuk setelah jatuh ke tangan penjahat.",
  str_guide_circle_S4boss_LtT = "Vilanor: Perangkap Terkutuk",
  str_guide_circle_S4boss_Rt = "Setelah menjadi Vilanor, kemampuannya sangat ditingkatkan, mendapatkan kekuatan untuk bergerak bebas melalui medan dan menghasilkan pedang dari energi jahat.",
  str_guide_circle_S4boss_RtT = "Karakteristik Musuh",
  str_guide_circle_S4boss_Lb = "Vilanor memiliki kemampuan untuk membuka ruang dan menciptakan Forbidden Walls, jadi kamu bisa menggunakan Aurorian yang memiliki kemampuan teleportasi untuk menginjak Exorcism Traps dan menyerang Vilanor dengan mudah setelah menghilangkan Forbidden Walls.",
  str_guide_circle_S4boss_LbT = "Strategi Melawan",
  str_guide_warn_16021911 = "Diperlukan untuk memilih 1 sekutu atau Shadow Piece untuk menggunakan Istvan: Skill Aktif Scarred Pith.",
  str_guide_warn_16021912 = "Ini adalah tempat kamu dapat melihat jumlah Shadow Endowments yang digunakan oleh sekutu saat ini. Tidak bisa dilemparkan pada sekutu ini jika jumlah yang digunakan tidak cukup.",
  str_guide_warn_16021913 = "Luncurkan skill pada Areia.",
  str_guide_warn_16021914 = "Dalam pertempuran ini, biaya skill ini +1 setiap kali Skill Aktif dilemparkan pada sekutu ini.",
  str_guide_warn_80040111 = "Navigator, lihat ke sini! Kamu telah mendapatkan kemampuan baru di dalam Mimpi!",
  str_guide_warn_80040112 = "Kemampuanmu akan semakin kuat seiring kamu semakin mendalami mimpi. Manfaatkanlah dengan baik!",
  str_guide_circle_shenghuaboss_Lt = "Super tentara ini adalah Eclipsite yang telah dilengkapi dengan perangkat mekanis di seluruh tubuhnya untuk membuatnya lebih tangguh, lebih ganas, dan lebih menakutkan.",
  str_guide_circle_shenghuaboss_LtT = "Super-Prajurit Blaugm",
  str_guide_circle_shenghuaboss_Rt = "Seorang prajurit super yang menakutkan yang unggul dalam menghancurkan musuh di sekitarnya dengan serangannya.",
  str_guide_circle_shenghuaboss_RtT = "Karakteristik Musuh",
  str_guide_circle_shenghuaboss_Lb = "Blaugm memiliki resistensi tinggi terhadap kerusakan Normal Attack, jadi coba untuk menimbulkan kerusakan dengan Chain Combo atau Active Skill.",
  str_guide_circle_shenghuaboss_LbT = "Strategi Melawan",
  str_guide_circle_ylxs_Lt = "Ulysses telah mengubah tubuhnya secara ekstensif untuk mewujudkan ide-ide ekstremnya. Dia bukan lagi seorang Aurorian sekarang.",
  str_guide_circle_ylxs_LtT = "Ulysses Bio",
  str_guide_circle_ylxs_Rt = "Ulysses menggunakan strategi serangan yang berbeda berdasarkan kemampuan dari Aurorian.",
  str_guide_circle_ylxs_RtT = "Karakteristik Musuh",
  str_guide_circle_ylxs_Lb = "Berdasarkan kondisi tim saat ini, serang dengan bijaksana dan hindari menerima kerusakan dari Ulysses untuk sangat meningkatkan peluang kemenangan.",
  str_guide_circle_ylxs_LbT = "Strategi Melawan",
  str_guide_warn_shzyx_01 = "Peringatan! Prototipe Guardian telah diaktifkan.",
  str_guide_warn_shzyx_02 = "Mesin kuno ini yang dibangun oleh Engineer tampaknya memiliki kesadaran diri.",
  str_guide_warn_shzyx_03 = "Membatasi Normal Attack, Active Skills, atau Chain Combos dari Aurorian. Juga merusak musuh dan melindungi sekutu secara bersamaan.",
  str_guide_warn_shzyx_04 = "Berdasarkan kondisi tim saat ini, seranglah dengan bijak untuk memiliki kesempatan berhadapan langsung dengannya. Jangan meremehkannya!",
  str_guide_circle_soilder1_Rt = "Senjata perang yang diciptakan melalui fusi antara Eclipsite dan Aurorian. Karakteristik Aurorian dipertahankan sebanyak mungkin, dan mekanisasi tidak terlalu jelas, tetapi masih sangat berbahaya.",
  str_guide_circle_soilder1_RtT = "Soldier Voidcross",
  str_guide_circle_soilder1_Rb = "Sebuah bentuk kehidupan mekanis yang menyerang dengan cara meretas dan memotong.",
  str_guide_circle_soilder1_RbT = "Karakteristik Musuh",
  str_guide_circle_soilder1_Lb = "Voidcross Soldier dapat memantulkan damage Normal Attack Aurorian. Jaga jarak dan coba untuk memberikan damage dengan Chain Combo atau Active Skill.",
  str_guide_circle_soilder1_LbT = "Strategi Melawan",
  str_guide_circle_soilder2_Rt = "Senjata perang yang diciptakan melalui fusi antara Eclipsite dan Aurorian. Senjata ini dilindungi oleh lapisan baju besi mekanik yang tebal, dan kekuatannya telah ditingkatkan sejauh mungkin.",
  str_guide_circle_soilder2_RtT = "Prajurit Ululat",
  str_guide_circle_soilder2_Rb = "Kekuatan dan pertahanan bentuk kehidupan mekanis yang telah dimodifikasi ini telah ditingkatkan secara signifikan, dan ia sangat ahli dalam menyerang dengan ledakan dan metode serupa lainnya.",
  str_guide_circle_soilder2_RbT = "Karakteristik Musuh",
  str_guide_circle_soilder2_Lb = "Soldier Ululat dapat memantulkan damage Normal Attack dari Aurorian. Perhatikan jangkauan serangan dan coba untuk memberikan damage dengan Chain Combos atau Active Skills.",
  str_guide_circle_soilder2_LbT = "Strategi Melawan",
  str_guide_circle_soilder3_Rt = "Senjata super yang diciptakan melalui fusi antara Eclipsite dan Aurorian. Ia tidak lagi memiliki karakteristik Aurorian dan kini menjadi eksistensi yang sepenuhnya mekanis.",
  str_guide_circle_soilder3_RtT = "Super-Soldier Meaugm",
  str_guide_circle_soilder3_Rb = "Bentuk kehidupan mekanis yang dimodifikasi ini dapat menggunakan baju besinya yang tebal sebagai senjata, membuatnya sangat sulit untuk ditangani.",
  str_guide_circle_soilder3_RbT = "Karakteristik Musuh",
  str_guide_circle_soilder3_Lb = "Super-Soldier Meaugm dapat memantulkan damage Serangan Normal Aurorian dan memulihkan HP sendiri, jadi cobalah untuk mengakhiri pertempuran secepat mungkin.",
  str_guide_circle_soilder3_LbT = "Strategi Melawan",
  str_guide_warn_14000101 = [[
Melalui Kabut, Gema dari Masa Lalu kini tersedia!
Mari mulai cerita baru di Bagian 2!]],
  str_guide_warn_14000102 = "Chapter cerita yang dibuka dalam event ini, serta chapter yang telah dijelajahi sejauh ini, ditampilkan di sini.",
  str_guide_warn_14000103 = "Ketuk Jelajahi Sekarang untuk langsung menuju peta Jelajah. Gunakan Prism di stage cerita utama dan stage Resource Raid untuk mendapatkan Bulu Caelestite.",
  str_guide_warn_14000104 = "Di Aurora Exchange, gunakan Bulu Caelestite untuk menukarkan berbagai hadiah.",
  str_guide_warn_14000105 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_14000106 = "Jangan lupa login ke game setiap hari untuk memperoleh reward Sign-In Navigasi.",
  str_guide_warn_14000107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_14100101 = "Drifting Begonia II: Cometh the Dragon, Spirits Begone kini tersedia! Saatnya bertemu teman baru dan memulai petualangan baru di Dragon's Dance!",
  str_guide_warn_14100102 = "Gunakan Prism di tahap Main Story dan tahap Resource Raid untuk mendapatkan Prayer Incense.",
  str_guide_warn_14100103 = "Di Absconding Evil, kita akan menghadapi serangkaian tantangan yang lebih kompleks.",
  str_guide_warn_14100104 = "Dalam Sea Blessings, gunakan Prayer Incense untuk menukarkan berbagai hadiah.",
  str_guide_warn_14100105 = "Jangan lupa login ke game setiap hari untuk memperoleh reward Sign-In Pengunjung.",
  str_guide_warn_14100106 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_warn_14100107 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_circle_yingzi_LtT = "Kehendak Jahat: Bayangan",
  str_guide_circle_yingzi_Lt = "Tercemar oleh Kehendak Jahat, kekuatan pemanggilannya telah berubah secara halus.",
  str_guide_circle_yingzi_RtT = "Karakteristik Musuh",
  str_guide_circle_yingzi_Rt = "Jumlah rune yang dipanggil setiap kali meningkat secara signifikan.",
  str_guide_circle_miran_LtT = "Kehendak Jahat: Murkmite",
  str_guide_circle_miran_Lt = "Tercemar oleh Kehendak Jahat, serangannya telah berubah secara halus.",
  str_guide_circle_miran_RtT = "Karakteristik Musuh",
  str_guide_circle_miran_Rt = "Saat mengenai, serangannya langsung mengurangi Force Point pemain sebanyak 2.",
  str_guide_circle_aogeyang_LtT = "Kehendak Jahat: Augean",
  str_guide_circle_aogeyang_Lt = "Tercemar oleh Kehendak Jahat, kemampuannya telah berubah secara halus.",
  str_guide_circle_aogeyang_RtT = "Karakteristik Musuh",
  str_guide_circle_aogeyang_Rt = "Mendapatkan peningkatan mobilitas yang signifikan dan, setiap 2 putaran, memanggil monster ke area terdekat untuk menyerang pemain bersama-sama.",
  str_guide_circle_jingmianta_LtT = "Reflector Tower: Divitalisasi",
  str_guide_circle_jingmianta_Lt = "Perangkat cermin yang berubah dalam lingkungan khusus, menawarkan bantuan kepada tim Aurorian.",
  str_guide_circle_jingmianta_RtT = "Karakteristik Jebakan",
  str_guide_circle_jingmianta_Rt = "Berposisi di lapangan memberikan energi khusus kepada tim, pemulihan Poin Kekuatan per putaran +1.",
  str_guide_circle_laolong_LtT = "Kehendak Jahat: Sangkar",
  str_guide_circle_laolong_Lt = "Dalam sangkar itu ada musuh yang dipenjara karena alasan tertentu. Setelah dibebaskan, mereka mungkin bisa membantu Bos atau mengekspos kerentanan Bos.",
  str_guide_circle_laolong_RtT = "Karakteristik Jebakan",
  str_guide_circle_laolong_Rt = "Ketuk perangkap dan habiskan 3 Force Points untuk membebaskan musuh dari kandang. Meskipun mereka tidak akan membantu Anda dalam pertempuran, kerusakan yang mereka terima akan sebagian ditransfer ke Bos.",
  str_guide_circle_paotai_LtT = "Menara Gesit",
  str_guide_circle_paotai_Lt = "Sebuah turret berkinerja tinggi. Meskipun memerlukan operasi manual, potensinya lebih efektif daripada yang otomatis.",
  str_guide_circle_paotai_RtT = "Karakteristik Jebakan",
  str_guide_circle_paotai_Rt = "Ketuk perangkap dan habiskan 2 Force Points untuk melancarkan 1 serangan, menimbulkan kerusakan dan debuff pada musuh dalam garis lurus di depan.",
  str_guide_circle_fengchuan_RtT = "Karakteristik Jebakan",
  str_guide_circle_fengchuan_Rt = "Menjadi lebih portabel dan mudah digunakan, mampu melepaskan skill dengan mengonsumsi Force Points dari tim.",
  str_guide_circle_8024001 = "Dalam Purging Evil in the Still Night, tim tidak lagi bergerak sesuai dengan aturan asli tetapi menggunakan Force Points untuk pergerakan.",
  str_guide_circle_8024002 = "Poin Kekuatan saat ini dari pemain ditampilkan di sebelah kiri, di mana pratinjau real-time dari Poin Kekuatan yang tersisa tersedia selama koneksi tile.",
  str_guide_circle_8024003 = "Gerakan sebelumnya tampaknya telah menghabiskan Force Points kamu. Tapi jangan khawatir; kamu akan menerima sejumlah Force Points di awal setiap ronde, dan pengisian ulang ronde berikutnya akan ditampilkan di sebelah kanan jauh.",
  str_guide_circle_8024004 = "Ketuk di sini untuk melihat efek bakat yang sedang aktif.",
  str_guide_circle_8024005 = "Force Point yang tidak terpakai di setiap putaran tidak akan hilang di akhir putaran. Terkadang, menyimpan Force Point dari sebuah putaran bisa menjadi pilihan yang bijaksana.",
  str_guide_season_talent_tree_1 = "Pilihan Knack terdiri dari beberapa Node Formasi dan Knack dan memberikan bonus tambahan. Mari kita mulai dengan mengaktifkan Node Formasi pertama!",
  str_guide_season_talent_tree_2 = "Ketuk Aktifkan untuk menggunakan Energi Auspicious untuk mengaktifkan Node Formasi pertama.",
  str_guide_season_talent_tree_3 = "Setelah Node Formasi diaktifkan, efeknya akan mulai berlaku dalam pertempuran. Juga dimungkinkan untuk membuka slot Knack di beberapa Node Formasi.",
  str_guide_season_talent_tree_4 = "Sekarang mari kita coba untuk mengaktifkan dan memasang Passive Skill pertama. Silakan ketuk Passive Skill ini.",
  str_guide_season_talent_tree_5 = "Ketuk Aktifkan untuk menghabiskan Energi Auspicious dan mengaktifkan Knack ini.",
  str_guide_season_talent_tree_6 = "Setelah mengaktifkan Knack, seret ke slot Knack yang sesuai untuk memasangnya dan menggunakan efeknya dalam pertempuran.",
  str_guide_season_talent_tree_7 = "Slot skill memiliki beberapa pembatasan tipe Skill. Slot Skill pertama hanya bisa dilengkapi dengan Skill Caelestite, dan slot lainnya hanya bisa dilengkapi dengan Passive Skills.",
  str_guide_season_talent_tree_8 = "Silakan lihat info gameplay untuk detail lebih lanjut tentang peraturan.",
  str_guide_season_trade_out_1 = "Daytime Merchant adalah gameplay baru di mana Navigator dapat mengelola pelabuhan dan kapal untuk mendapatkan Modal Kerja dan Energi Auspicious.",
  str_guide_season_trade_out_2 = "Membersihkan Kevilan di Malam yang Tenang adalah gameplay baru dengan tahap linear. Dalam gameplay ini, Navigator akan bergerak sesuai dengan sistem baru dan menggunakan Feng Shui Knacks untuk mendapatkan keuntungan dalam pertempuran!",
  str_guide_season_trade_in_1 = "Navigator perlu mengelola pelabuhan dan kapal dan dapat mengetuk Renovation Upgrade di sudut kanan atas untuk meningkatkan target yang dipilih.",
  str_guide_season_trade_in_2 = "Tingkat pelabuhan dan kapal akan mempengaruhi kecepatan pembongkaran pelabuhan, beban yang tersisa dari kapal, dan waktu yang diperlukan untuk membongkar barang setelah menyelesaikan pelayaran.",
  str_guide_season_trade_in_3 = "Anggota kru yang dipekerjakan dapat ditugaskan ke berbagai kapal, tetapi setiap anggota kru hanya dapat ditugaskan ke satu kapal dalam satu waktu.",
  str_guide_season_trade_in_4 = "Anggota kru memiliki atribut Dispatch, Kapasitas Pengiriman, dan Kesiapan. Tingkatkan pelabuhan untuk merekrut anggota kru yang lebih mampu.",
  str_guide_season_trade_in_5 = "Status Kapal dari setiap kapal ditentukan oleh Ability Points dari anggota kru yang ditugaskan ke kapal. Jika sebuah kapal tidak memenuhi persyaratan level kapal, Status Kapalnya akan jauh lebih rendah, yang akan mempengaruhi keuntungannya.",
  str_guide_season_trade_in_6 = "Tembus berbagai target tahapan Modal Kerja dari pelayaran untuk meningkatkan Level Kemakmuran Guild dan klaim hadiah tambahan!",
  str_guide_season_trade_in_7 = "Berusaha keras untuk meningkatkan pelabuhan dan kapal, menugaskan anggota kru yang sesuai ke kapal, dan merespon dengan tepat terhadap insiden pelayaran untuk mendapatkan lebih banyak keuntungan dari pelayaran!",
  str_guide_season_trade_in_8 = "Silakan lihat info gameplay untuk detail lebih lanjut tentang peraturan.",
  str_guide_mouse_Rt = "Fiendlings omnivora berukuran kecil dengan budidaya yang tidak cukup, menjaga sifat liar mereka. Mereka selalu menyelinap ke tempat tinggal Aurorian untuk mencuri makanan. Beberapa yang agresif bahkan mungkin menyebabkan kerusakan.",
  str_guide_mouse_RtT = "Fiendling: Tikus",
  str_guide_mouse_Lt = "Lincah dan cepat, ia dengan gesit bergerak ke belakang target setelah serangan.",
  str_guide_mouse_LtT = "Karakteristik Musuh",
  str_guide_mouse_Lb = "Menargetkan Aurorian dengan DEF terendah dalam tim saat menyerang, memberikan damage. Cobalah untuk menghindari penempatan Aurorian dengan DEF rendah ke dalam pertempuran.",
  str_guide_mouse_LbT = "Strategi Melawan",
  str_guide_circle_2909301_Lt = "Legenda mengatakan bahwa pada malam Festival Musim Semi, sebuah fiendlings yang mirip dengan binatang buas turun ke Longzhou, menyebabkan kekacauan. Mereka yang berhasil mengusirnya akan diberkati dengan setahun penuh damai dan keberuntungan.",
  str_guide_circle_2909301_LtT = "Fiendling: Nian",
  str_guide_circle_2909301_Rt = "Gunakan Active Skills untuk menakuti Nian, memperlambat kemajuannya.",
  str_guide_circle_2909301_RtT = "Strategi Melawan",
  str_guide_circle_2909301_Lb = "Melompat ke depan dan memberikan damage, membuat 1 klaster di sekitarnya tidak dapat dilalui. Jika Nian menghancurkan gerbang, pertempuran berakhir dengan kekalahan.",
  str_guide_circle_2909301_LbT = "Karakteristik Musuh",
  str_guide_circle_80050001_Rt = "Mendapatkan 10 poin Energi Tempur di awal setiap putaran. Memberikan peningkatan ATK kepada semua monster di lapangan jika ada lebih dari 30 poin energi di akhir putaran.",
  str_guide_circle_80050001_RtT = "Intel Eclipsite - Kurir",
  str_guide_circle_80050001_Rb = "Ketika Aurorian memberikan kerusakan pada Kurir dengan Skill Aktif dan Serangan Normal, mereka dapat mengurangi Energi Tempur Kurir. Kurir menimbulkan kerusakan pada semua monster di lapangan saat eliminasi.",
  str_guide_circle_80050001_RbT = "Strategi Melawan",
  str_guide_warn_80050111 = "Navigator, lihat ke sini! Kamu telah mendapatkan kemampuan baru di dalam Mimpi!",
  str_guide_warn_80050112 = "Kemampuanmu akan semakin kuat seiring kamu semakin mendalami mimpi. Manfaatkanlah dengan baik!",
  str_guide_circle_80150101 = "Tim tidak lagi bergerak sesuai dengan aturan asli tetapi menggunakan Force Points untuk pergerakan, terlepas dari warna petak.",
  str_guide_circle_80150102 = "Ditampilkan di sini adalah Poin Gaya pemain, yang terdaftar dari kiri ke kanan sebagai Poin Gaya Saat Ini, Penyimpanan Maksimum, dan Pemulihan Poin Gaya.",
  str_guide_circle_80150103 = "Pada awal setiap putaran, pemain secara otomatis memulihkan Poin Kekuatan berdasarkan jumlah yang ditampilkan dalam Pemulihan Poin Kekuatan, yang meningkat setiap putarannya.",
  str_guide_circle_80150201 = "Dalam gameplay ini, pemain mendapatkan kembali 1 Force Point untuk setiap Dark Tile yang dikonsumsi.",
  str_guide_circle_80150301 = "Ketuk untuk memilih Batu dan gunakan Force Points untuk membersihkannya.",
  str_guide_circle_80250101 = "Dalam gameplay ini, ketika pemain melepaskan keterampilan Chain Combo, Dark Tiles dianggap sebagai 2 tile untuk konsumsi.",
  str_guide_circle_2921201_Lt = "Kapten dari Silent Hunters kini telah mengarahkan pedangnya pada rekan satu tim yang selalu mempercayainya... Inilah sejauh mana dia telah berkompromi dengan kerajaan.",
  str_guide_circle_2921201_LtT = "Claymore",
  str_guide_circle_2921201_Rt = "Berdasarkan kondisi medan perang, Claymore dapat memilih untuk bergerak dengan menghubungkan tile dan kemudian menyerang, atau meluncurkan Double Strike setelah gerakan biasa. Saat HP menurun, dia dapat melepaskan keterampilan khusus untuk mengukir medan perang, bertarung dengan lawan di ruang yang lebih terbatas.",
  str_guide_circle_2921201_RtT = "Karakteristik Musuh",
  str_guide_circle_2921201_Lb = "Pastikan untuk tidak terkena serangan dari keahlian khusus; sisanya tergantung pada kemampuan Anda.",
  str_guide_circle_2921201_LbT = "Strategi Melawan",
  str_guide_circle_2909401_Lt = "Sebuah Wraith yang misterius dan tangguh, menjelajahi tanah untuk berlatih. Napasnya memancarkan teror, meramalkan malapetaka bagi mereka yang membangkitkan kemarahannya.",
  str_guide_circle_2909401_LtT = "Ira",
  str_guide_circle_2909401_Rt = "Mampu memanggil Shadowfire dengan Darkflow dalam pertempuran.",
  str_guide_circle_2909401_RtT = "Karakteristik Musuh",
  str_guide_circle_2909401_Lb = "Catatan: Meteorit Darkflow milik Ira, yang terdiri dari api yang mengamuk, dapat seketika membunuh Aurorian dalam jangkauannya. Perhatikan area peringatan dan hindari segera!",
  str_guide_circle_2909401_LbT = "Strategi Melawan",
  str_guide_n43_1 = [[
Glimmers of Light kini tersedia!
Mari mulai cerita baru di Interlude Kedua!]],
  str_guide_n43_2 = "Chapter cerita yang terbuka dalam event ini, serta chapter yang telah dijelajahi sejauh ini, ditampilkan di sini.",
  str_guide_n43_3 = "Ketuk Jelajahi Sekarang untuk langsung menuju peta Jelajah. Gunakan Prism di stage cerita utama dan stage Resource Raid untuk mendapatkan Bulu Caelestite.",
  str_guide_n43_4 = "Di Aurora Exchange, gunakan Bulu Caelestite untuk menukarkan berbagai hadiah.",
  str_guide_n43_5 = "Ikuti Story Stage event dan selesaikan quest dalam Special Event Book!",
  str_guide_n43_6 = "Jangan lupa login ke game setiap hari untuk memperoleh reward Sign-In Navigasi.",
  str_guide_n43_7 = "Jika ada pertanyaan tentang event tersebut, kamu dapat melihat deskripsi detailnya di sini.",
  str_guide_warn_90010702 = "Pemberitahuan: Ketuk di sini untuk membuka layar Dream Orb.",
  str_guide_warn_90010703 = "Pemberitahuan: Ada beberapa slot di Spiral Pencerahan. Tempatkan Orb Mimpi ke dalam slot kosong untuk menganalisanya dan melepaskan kekuatannya.",
  str_guide_warn_90010704 = "Pemberitahuan: Ketuk pada Dream Orb untuk melihat detailnya.",
  str_guide_warn_90010705 = "Pemberitahuan: Ketuk tombol Equip untuk meletakkan Dream Orb ke dalam Enlightenment Spiral. Anda juga dapat menyeret Dream Orb langsung ke slot kosong.",
  str_guide_warn_90010706 = "Komentar: Energi yang cukup diperlukan untuk melepaskan kekuatan Dream Orbs di Enlightenment Spiral. Tapi jangan khawatir; sebagai Enlightenermu, saya percaya kamu bisa mengumpulkan cukup energi dalam pertempuran.",
  str_guide_warn_90010707 = "Pemberitahuan: Jika Anda memiliki beberapa Dream Orb, pertimbangkan untuk menggabungkannya untuk mendapatkan Dream Orb level yang lebih tinggi.",
  str_guide_warn_90010708 = "Dua Dream Orb dengan level yang sama dapat disintesis menjadi 1 Dream Orb yang levelnya 1 tingkat lebih tinggi.",
  str_guide_warn_90010709 = "Pemberitahuan: Jika ada pertanyaan, kamu dapat melihat deskripsi lengkapnya di sini.",
  str_guide_circle_2004901_LbT = "Kabut asap",
  str_guide_circle_2004901_Lb = "Terbentuk dari akumulasi Darkflow yang cepat di sekitar musuh yang telah mati. Hati-hati! Amarah dan dendam musuhmu masih hidup di dalamnya.",
  str_guide_circle_2004901_RtT = "Karakteristik Musuh",
  str_guide_circle_2004901_Rt = [[
Semua kerusakan yang diterimanya dikurangi menjadi 1. Ia tidak bisa menyerang tetapi akan terus bergerak menuju Aurorian.
Haze tidak dihitung untuk penyegaran gelombang dan kondisi kemenangan tahap.]],
  str_guide_circle_2004901_RbT = "Strategi Melawan",
